def get_workspace_hierarchy(workspaceId, includeArchived=None, maxDepth=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    def _log(status, resolved_workspace_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now,
            "tool": "get_workspace_hierarchy",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": resolved_workspace_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_log.json", logs)

    def _validate_bool(v, name):
        if v is None:
            return True, None
        if isinstance(v, bool):
            return True, None
        return False, _err("VALIDATION_ERROR", f"{name} must be a boolean")

    def _validate_int(v, name):
        if v is None:
            return True, None
        if isinstance(v, bool) or not isinstance(v, int):
            return False, _err("VALIDATION_ERROR", f"{name} must be an integer")
        return True, None

    # --- input validation ---
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspaceId is invalid; expected pattern ^cu_wsp_[0-9A-Z]{18,}$")

    ok, e = _validate_bool(includeArchived, "includeArchived")
    if not ok:
        _log("error", None, "VALIDATION_ERROR")
        return e
    ok, e = _validate_int(maxDepth, "maxDepth")
    if not ok:
        _log("error", None, "VALIDATION_ERROR")
        return e
    if maxDepth is None:
        maxDepth = 3
    if maxDepth < 1 or maxDepth > 3:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "maxDepth must be between 1 and 3")

    include_archived = bool(includeArchived) if includeArchived is not None else False

    # --- resolve workspace (ambient auth: pick a working workspace) ---
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspaceId:
            ws = w
            break
    if ws is None or ws.get("status") != "active":
        _log("error", workspaceId if ws else None, "NOT_FOUND")
        return _err("NOT_FOUND", "workspace not found or not active")

    containers = _load("containers.json")
    if not isinstance(containers, list):
        containers = []

    # Only active containers are returned; archived is controlled by includeArchived
    active = []
    for c in containers:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != workspaceId:
            continue
        if c.get("status") != "active":
            continue
        if not include_archived and c.get("archived") is True:
            continue
        active.append(c)

    by_id = {c["id"]: c for c in active if isinstance(c.get("id"), str)}
    # enforce parent-child relationships within active set only
    spaces = [c for c in active if c.get("type") == "space" and c.get("parent_id") in (None, "")]
    folders = [c for c in active if c.get("type") == "folder"]
    lists_ = [c for c in active if c.get("type") == "list"]

    def _children_of(parent_id, type_=None):
        out = []
        for c in active:
            if c.get("parent_id") == parent_id:
                if type_ is None or c.get("type") == type_:
                    out.append(c)
        out.sort(key=lambda x: (str(x.get("name") or "").lower(), x.get("id") or ""))
        return out

    def _serialize_container(c):
        # minimal safe projection
        return {
            "id": c.get("id"),
            "clickupId": c.get("clickup_id"),
            "type": c.get("type"),
            "name": c.get("name"),
            "parentId": c.get("parent_id"),
            "archived": c.get("archived"),
            "content": c.get("content"),
            "dueDate": c.get("due_date"),
            "priority": c.get("priority"),
            "assigneeMemberId": c.get("assignee_member_id"),
            "overrideStatuses": c.get("override_statuses"),
            "createdAt": c.get("created_at"),
            "updatedAt": c.get("updated_at"),
        }

    tree_spaces = []
    for sp in sorted(spaces, key=lambda x: (str(x.get("name") or "").lower(), x.get("id") or "")):
        sp_node = _serialize_container(sp)
        if maxDepth >= 2:
            sp_folders = _children_of(sp.get("id"), "folder")
            sp_node["folders"] = []
            for fo in sp_folders:
                fo_node = _serialize_container(fo)
                if maxDepth >= 3:
                    fo_lists = _children_of(fo.get("id"), "list")
                    fo_node["lists"] = [_serialize_container(li) for li in fo_lists]
                sp_node["folders"].append(fo_node)
            if maxDepth >= 3:
                # lists directly under space (parent can be space)
                sp_lists = _children_of(sp.get("id"), "list")
                sp_node["lists"] = [_serialize_container(li) for li in sp_lists]
        tree_spaces.append(sp_node)

    _log("ok", workspaceId, None)
    return {
        "workspace": {"id": ws.get("id"), "name": ws.get("name"), "clickupTeamId": ws.get("clickup_team_id")},
        "includeArchived": include_archived,
        "maxDepth": maxDepth,
        "spaces": tree_spaces,
        "meta": {"spaces": len(tree_spaces), "containers_total_active": len(active)},
    }

def create_task(name, listId=None, listName=None, parent=None, description=None, status=None, priority=None, startDate=None, dueDate=None, timeEstimateMs=None, assignees=None, customFields=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_task"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        try:
            ss = s.strip()
            ss2 = ss[:-1] if ss.endswith("Z") else ss
            dt = datetime.datetime.fromisoformat(ss2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt.isoformat().replace("+00:00", "Z"), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}{''.join(secrets.choice(alphabet) for _ in range(22))}"

    # ---- Validate inputs ----
    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", rule="name <> ''")
        _log("error", "VALIDATION_ERROR")
        return e
    task_name = name.strip()

    if listId is None and listName is None:
        e = _err("VALIDATION_ERROR", "Provide listId or listName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if listId is not None and (not isinstance(listId, str) or not listId.strip()):
        e = _err("VALIDATION_ERROR", "listId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        e = _err("VALIDATION_ERROR", "listName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if parent is not None and (not isinstance(parent, str) or not parent.strip()):
        e = _err("VALIDATION_ERROR", "parent must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if status is not None and (not isinstance(status, str) or not status.strip()):
        e = _err("VALIDATION_ERROR", "status must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if priority is not None:
        if not isinstance(priority, int):
            e = _err("VALIDATION_ERROR", "priority must be an integer when provided.")
            _log("error", "VALIDATION_ERROR")
            return e
        if priority < 0 or priority > 4:
            e = _err("VALIDATION_ERROR", "priority must be between 0 and 4.", rule="priority is null or (priority >= 0 and priority <= 4)")
            _log("error", "VALIDATION_ERROR")
            return e

    start_iso, err = _parse_dt(startDate, "startDate")
    if err:
        _log("error", err["error"]["code"])
        return err
    due_iso, err = _parse_dt(dueDate, "dueDate")
    if err:
        _log("error", err["error"]["code"])
        return err

    if timeEstimateMs is not None:
        if not isinstance(timeEstimateMs, int):
            e = _err("VALIDATION_ERROR", "timeEstimateMs must be an integer when provided.")
            _log("error", "VALIDATION_ERROR")
            return e
        if timeEstimateMs < 0:
            e = _err("VALIDATION_ERROR", "timeEstimateMs must be non-negative.", rule="time_estimate_ms is null or time_estimate_ms >= 0")
            _log("error", "VALIDATION_ERROR")
            return e

    if assignees is not None:
        if not isinstance(assignees, list):
            e = _err("VALIDATION_ERROR", "assignees must be an array when provided.")
            _log("error", "VALIDATION_ERROR")
            return e
        for a in assignees:
            if not isinstance(a, str) or not a.strip():
                e = _err("VALIDATION_ERROR", "assignees must be an array of non-empty strings.")
                _log("error", "VALIDATION_ERROR")
                return e

    if customFields is not None:
        if not isinstance(customFields, list):
            e = _err("VALIDATION_ERROR", "customFields must be an array when provided.")
            _log("error", "VALIDATION_ERROR")
            return e
        for cf in customFields:
            if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or len(cf.keys()) != 2:
                e = _err("VALIDATION_ERROR", "Each customFields entry must be an object with exactly {id, value}.")
                _log("error", "VALIDATION_ERROR")
                return e
            if not isinstance(cf.get("id"), str) or not cf["id"].strip():
                e = _err("VALIDATION_ERROR", "customFields[].id must be a non-empty string.")
                _log("error", "VALIDATION_ERROR")
                return e

    # ---- Load datastore ----
    containers = _load("containers.json")
    tasks = _load("tasks.json")
    members = _load("members.json")
    workspaces = _load("workspaces.json")
    if not isinstance(containers, list):
        containers = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(members, list):
        members = []
    if not isinstance(workspaces, list):
        workspaces = []

    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("id")}
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}

    # ---- Resolve destination list ----
    dest_list = None
    if listId is not None:
        lid = listId.strip()
        # NOTE: Do not hard-fail on pattern; accept caller values and resolve by actual ids.
        c = cont_by_id.get(lid)
        if c and c.get("type") == "list" and c.get("status") == "active":
            dest_list = c
        else:
            # Some callers incorrectly pass workspace id; try treating listId as workspaceId with listName.
            if listName is not None and lid in ws_by_id:
                candidates = [x for x in containers if isinstance(x, dict) and x.get("type") == "list" and x.get("status") == "active" and x.get("workspace_id") == lid and x.get("name") == listName.strip()]
                if len(candidates) == 1:
                    dest_list = candidates[0]
                elif len(candidates) > 1:
                    e = _err("CONFLICT", "listName is ambiguous within the specified workspace.", listName=listName.strip(), workspaceId=lid, matches=len(candidates))
                    _log("error", "CONFLICT")
                    return e
            # if still not found, fall through to NOT_FOUND below
    else:
        ln = listName.strip()
        candidates = [x for x in containers if isinstance(x, dict) and x.get("type") == "list" and x.get("status") == "active" and x.get("name") == ln]
        if len(candidates) == 1:
            dest_list = candidates[0]
        elif len(candidates) == 0:
            dest_list = None
        else:
            e = _err("CONFLICT", "listName is ambiguous; provide listId to disambiguate.", listName=ln, matches=len(candidates))
            _log("error", "CONFLICT")
            return e

    if not dest_list:
        e = _err("NOT_FOUND", "Destination list not found.", listId=listId, listName=listName)
        _log("error", "NOT_FOUND")
        return e

    workspace_id = dest_list.get("workspace_id")
    ws = ws_by_id.get(workspace_id)
    if not ws or ws.get("status") != "active":
        # If the list exists but workspace not active, treat as unauthorized/unavailable rather than not found
        e = _err("UNAUTHORIZED", "Workspace is not available for task creation.", workspaceId=workspace_id, workspaceStatus=(ws.get("status") if ws else None))
        _log("error", "UNAUTHORIZED")
        return e

    # ---- Resolve parent task (if any) ----
    parent_task_id = None
    if parent is not None:
        pid = parent.strip()
        matches = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("workspace_id") != workspace_id:
                continue
            if t.get("status") != "active":
                continue
            if t.get("clickup_task_id") == pid or (t.get("custom_task_id") and t.get("custom_task_id") == pid) or t.get("id") == pid:
                matches.append(t)
        # ambiguity rule: if both clickup_task_id and custom_task_id match different tasks
        # (we approximated by collecting all matches)
        if len(matches) == 0:
            e = _err("NOT_FOUND", "Parent task not found in the destination workspace.", parent=pid)
            _log("error", "NOT_FOUND")
            return e
        uniq_ids = {m.get("id") for m in matches if m.get("id")}
        if len(uniq_ids) > 1:
            e = _err("CONFLICT", "Parent task id is ambiguous (matches multiple tasks).", parent=pid, matches=len(uniq_ids))
            _log("error", "CONFLICT")
            return e
        parent_task_id = matches[0].get("id")

    # ---- Resolve assignees to clickup_user_ids ----
    assignee_clickup_user_ids = []
    if assignees:
        mrows = [m for m in members if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("status") == "active"]
        for a in assignees:
            token = a.strip()
            resolved = None
            # prefer direct clickup_user_id match
            for m in mrows:
                if m.get("clickup_user_id") == token:
                    resolved = m
                    break
            if not resolved:
                for m in mrows:
                    if m.get("email") and m.get("email").lower() == token.lower():
                        resolved = m
                        break
            if not resolved:
                for m in mrows:
                    if m.get("username") and m.get("username").lower() == token.lower():
                        resolved = m
                        break
            if resolved and resolved.get("clickup_user_id") not in assignee_clickup_user_ids:
                assignee_clickup_user_ids.append(resolved.get("clickup_user_id"))
            # If cannot resolve, ClickUp often tolerates unknown assignee ids; keep raw token if it looks like an id.
            if not resolved and token and token not in assignee_clickup_user_ids:
                assignee_clickup_user_ids.append(token)

    # ---- Status validation: not modeled; accept and store ----
    status_name = status.strip() if isinstance(status, str) and status.strip() else None

    # ---- Enforce uniqueness of clickup_task_id/custom_task_id if we generate them ----
    # Since this tool surface doesn't accept clickup_task_id, we generate one and ensure unique.
    existing_clickup_ids = {t.get("clickup_task_id") for t in tasks if isinstance(t, dict) and t.get("workspace_id") == workspace_id}
    new_clickup_task_id = _gen_id("cuclk_")  # upstream-like, not the internal id
    while new_clickup_task_id in existing_clickup_ids:
        new_clickup_task_id = _gen_id("cuclk_")

    now = _now()
    new_row = {
        "id": _gen_id("cu_tsk_"),
        "workspace_id": workspace_id,
        "list_container_id": dest_list.get("id"),
        "parent_task_id": parent_task_id,
        "clickup_task_id": new_clickup_task_id,
        "custom_task_id": None,
        "name": task_name,
        "description": (description if description is not None else None),
        "status_name": status_name,
        "priority": priority,
        "start_date": start_iso,
        "due_date": due_iso,
        "time_estimate_ms": timeEstimateMs,
        "assignee_clickup_user_ids": assignee_clickup_user_ids,
        "custom_fields": (customFields if customFields is not None else []),
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # ---- Persist ----
    tasks.append(new_row)
    _save("tasks.json", tasks)

    _log("ok", meta={"task_id": new_row["id"], "workspace_id": workspace_id, "list_container_id": new_row["list_container_id"]})
    return {"task": new_row}

def get_task(taskId=None, taskName=None, listName=None, subtasks=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, workspace_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now,
            "tool": "get_task",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_log.json", logs)

    if taskId is None and taskName is None:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "either taskId or taskName is required")
    if taskId is not None and not isinstance(taskId, str):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskId must be a string")
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string")
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided")
    if subtasks is not None and not isinstance(subtasks, bool):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subtasks must be a boolean")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    containers = _load("containers.json")
    if not isinstance(containers, list):
        containers = []

    def _resolve_list_by_name_in_workspace(workspace_id, ln):
        matches = [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == ln]
        if len(matches) == 1:
            return matches[0]
        return None

    def _task_matches_id(t, tid):
        return t.get("id") == tid or t.get("clickup_task_id") == tid or (t.get("custom_task_id") and t.get("custom_task_id") == tid)

    resolved = None
    workspace_id = None

    if taskId is not None:
        # Ambiguity rule: if clickup_task_id and custom_task_id match different tasks -> conflict
        matches = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and _task_matches_id(t, taskId)]
        uniq = {m.get("id") for m in matches}
        if len(uniq) == 0:
            _log("error", None, "NOT_FOUND")
            return _err("NOT_FOUND", "task not found")
        if len(uniq) > 1:
            _log("error", None, "CONFLICT")
            return _err("CONFLICT", "taskId is ambiguous; it matches multiple tasks", matches=list(uniq))
        resolved = matches[0]
        workspace_id = resolved.get("workspace_id")
    else:
        # taskName search across all workspaces; must not pick arbitrarily if ambiguous
        candidates = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("name") == taskName.strip()]
        if listName is not None:
            # reduce by listName within each workspace by matching task.list_container_id -> list container name
            list_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active"}
            filtered = []
            for t in candidates:
                li = list_by_id.get(t.get("list_container_id"))
                if li and li.get("name") == listName:
                    filtered.append(t)
            candidates = filtered

        uniq = {t.get("id") for t in candidates}
        if len(uniq) == 0:
            _log("error", None, "NOT_FOUND")
            return _err("NOT_FOUND", "task not found")
        if len(uniq) > 1:
            _log("error", None, "CONFLICT")
            return _err("CONFLICT", "taskName is ambiguous; multiple active tasks match", matches=list(uniq))
        resolved = candidates[0]
        workspace_id = resolved.get("workspace_id")

    out = dict(resolved)
    if subtasks:
        subs = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("workspace_id") == workspace_id and t.get("parent_task_id") == resolved.get("id")]
        subs.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))
        out["subtasks"] = subs

    _log("ok", workspace_id, None)
    return {"task": out}

def update_task(taskId=None, taskName=None, listName=None, name=None, description=None, status=None, priority=None, startDate=None, dueDate=None, timeEstimateMs=None, assignees=None, customFields=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, workspace_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now,
            "tool": "update_task",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_log.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            ss = s[:-1] if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            return dt.replace(microsecond=0).isoformat() + ("Z" if s.endswith("Z") else ""), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    # identifier validation
    if taskId is None and taskName is None:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "either taskId or taskName is required")
    if taskId is not None and not isinstance(taskId, str):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskId must be a string")
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string")
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided")

    # at least one change
    provided = {
        "name": name, "description": description, "status": status, "priority": priority,
        "startDate": startDate, "dueDate": dueDate, "timeEstimateMs": timeEstimateMs,
        "assignees": assignees, "customFields": customFields
    }
    if all(v is None for v in provided.values()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "at least one update field must be provided")

    # field validations
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string")
    if status is not None and not isinstance(status, str):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be a string")
    if priority is not None:
        if isinstance(priority, bool) or not isinstance(priority, int):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer")
        if priority < 0 or priority > 4:
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be between 0 and 4")
    if timeEstimateMs is not None:
        if isinstance(timeEstimateMs, bool) or not isinstance(timeEstimateMs, int):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "timeEstimateMs must be an integer")
        if timeEstimateMs < 0:
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "timeEstimateMs must be non-negative")

    start_iso, e = _parse_dt(startDate, "startDate")
    if e:
        _log("error", None, "VALIDATION_ERROR")
        return e
    due_iso, e = _parse_dt(dueDate, "dueDate")
    if e:
        _log("error", None, "VALIDATION_ERROR")
        return e

    if assignees is not None:
        if not isinstance(assignees, list) or any(not isinstance(a, str) for a in assignees):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assignees must be an array of strings")

    if customFields is not None:
        if not isinstance(customFields, list):
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "customFields must be an array of {id,value} objects")
        for i, cf in enumerate(customFields):
            if not isinstance(cf, dict):
                _log("error", None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"customFields[{i}] must be an object")
            if set(cf.keys()) - {"id", "value"}:
                _log("error", None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"customFields[{i}] has unknown properties")
            if "id" not in cf or "value" not in cf:
                _log("error", None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"customFields[{i}] must include id and value")
            if not isinstance(cf["id"], str) or not cf["id"].strip():
                _log("error", None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"customFields[{i}].id must be a non-empty string")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    containers = _load("containers.json")
    if not isinstance(containers, list):
        containers = []
    members = _load("members.json")
    if not isinstance(members, list):
        members = []

    def _task_matches_id(t, tid):
        return t.get("id") == tid or t.get("clickup_task_id") == tid or (t.get("custom_task_id") and t.get("custom_task_id") == tid)

    resolved = None
    idx = None
    workspace_id = None

    if taskId is not None:
        matches = [(i, t) for i, t in enumerate(tasks) if isinstance(t, dict) and t.get("status") == "active" and _task_matches_id(t, taskId)]
        uniq = {t.get("id") for _, t in matches}
        if len(uniq) == 0:
            _log("error", None, "NOT_FOUND")
            return _err("NOT_FOUND", "task not found")
        if len(uniq) > 1:
            _log("error", None, "CONFLICT")
            return _err("CONFLICT", "taskId is ambiguous; it matches multiple tasks", matches=list(uniq))
        idx, resolved = matches[0]
        workspace_id = resolved.get("workspace_id")
    else:
        candidates = [(i, t) for i, t in enumerate(tasks) if isinstance(t, dict) and t.get("status") == "active" and t.get("name") == taskName.strip()]
        if listName is not None:
            list_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active"}
            filtered = []
            for i, t in candidates:
                li = list_by_id.get(t.get("list_container_id"))
                if li and li.get("name") == listName:
                    filtered.append((i, t))
            candidates = filtered
        uniq = {t.get("id") for _, t in candidates}
        if len(uniq) == 0:
            _log("error", None, "NOT_FOUND")
            return _err("NOT_FOUND", "task not found")
        if len(uniq) > 1:
            _log("error", None, "CONFLICT")
            return _err("CONFLICT", "taskName is ambiguous; multiple active tasks match", matches=list(uniq))
        idx, resolved = candidates[0]
        workspace_id = resolved.get("workspace_id")

    # validate list exists and is a list container
    list_container = next((c for c in containers if isinstance(c, dict) and c.get("id") == resolved.get("list_container_id") and c.get("type") == "list"), None)
    if list_container is None or list_container.get("status") != "active":
        _log("error", workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "task list container not found or not active")

    # resolve assignees to clickup_user_ids (if provided)
    assignee_clickup_user_ids = None
    if assignees is not None:
        ws_members = [m for m in members if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("status") == "active"]
        resolved_ids = []
        for a in assignees:
            a_norm = a.strip()
            found = None
            for m in ws_members:
                if m.get("clickup_user_id") == a_norm:
                    found = m
                    break
            if found is None:
                for m in ws_members:
                    if isinstance(m.get("email"), str) and m.get("email").lower() == a_norm.lower():
                        found = m
                        break
            if found is None:
                for m in ws_members:
                    if isinstance(m.get("username"), str) and m.get("username").lower() == a_norm.lower():
                        found = m
                        break
            if found is None:
                _log("error", workspace_id, "NOT_FOUND")
                return _err("NOT_FOUND", f"assignee not found in workspace: {a}")
            resolved_ids.append(found.get("clickup_user_id"))
        assignee_clickup_user_ids = resolved_ids

    # status validity not modeled; accept string, normalize empty->None
    new_status_name = None
    if status is not None:
        new_status_name = status.strip() if status.strip() else None

    # apply changes and ensure effect
    before = dict(resolved)
    changed = False

    if name is not None and resolved.get("name") != name.strip():
        resolved["name"] = name.strip()
        changed = True
    if description is not None and resolved.get("description") != description:
        resolved["description"] = description
        changed = True
    if status is not None and resolved.get("status_name") != new_status_name:
        resolved["status_name"] = new_status_name
        changed = True
    if priority is not None and resolved.get("priority") != priority:
        resolved["priority"] = priority
        changed = True
    if startDate is not None and resolved.get("start_date") != start_iso:
        resolved["start_date"] = start_iso
        changed = True
    if dueDate is not None and resolved.get("due_date") != due_iso:
        resolved["due_date"] = due_iso
        changed = True
    if timeEstimateMs is not None and resolved.get("time_estimate_ms") != timeEstimateMs:
        resolved["time_estimate_ms"] = timeEstimateMs
        changed = True
    if assignee_clickup_user_ids is not None and resolved.get("assignee_clickup_user_ids") != assignee_clickup_user_ids:
        resolved["assignee_clickup_user_ids"] = assignee_clickup_user_ids
        changed = True
    if customFields is not None and resolved.get("custom_fields") != customFields:
        resolved["custom_fields"] = customFields
        changed = True

    if not changed:
        _log("error", workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "no changes detected; provide at least one field with a different value")

    resolved["updated_at"] = now
    tasks[idx] = resolved
    _save("tasks.json", tasks)

    _log("ok", workspace_id, None)
    return {"task": resolved}

def move_task(taskId=None, taskName=None, sourceListName=None, listId=None, listName=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage/audit logging support (best-effort: only if a collection exists)
    def _log(status, credential_id=None, details=None):
        fname = "request_log.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        rows = _load(fname)
        rid = "cu_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % int((time.time() % 1) * 1_000_000))
        rows.append({
            "id": rid,
            "endpoint": "move_task",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now,
            "details": details or {}
        })
        _save(fname, rows)

    # Ambient auth: pick any active workspace (must not fail if no explicit credential param)
    workspaces = _load("workspaces.json")
    workspace = next((w for w in workspaces if w.get("status") == "active"), None)
    if not workspace:
        _log("error", None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active workspace available to serve this request.")
    workspace_id = workspace.get("id")

    # Validate input schema constraints (anyOf + oneOf)
    if not isinstance(taskId, (str, type(None))) or not isinstance(taskName, (str, type(None))) or not isinstance(sourceListName, (str, type(None))) or not isinstance(listId, (str, type(None))) or not isinstance(listName, (str, type(None))):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid parameter types.")
    if taskId is None and (taskName is None or sourceListName is None):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Provide either taskId, or taskName + sourceListName.")
    if taskId is not None and (taskName is not None or sourceListName is not None):
        # allow but prefer taskId; still validate
        pass
    if (listId is None and listName is None) or (listId is not None and listName is not None):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Provide exactly one of listId or listName.")
    if listId is not None:
        if not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", listId):
            _log("error", None, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "listId format is invalid.", field="listId")

    containers = _load("containers.json")
    tasks = _load("tasks.json")

    def _find_active_list_by_id(cid):
        return next((c for c in containers if c.get("id") == cid and c.get("workspace_id") == workspace_id and c.get("status") == "active" and c.get("type") == "list"), None)

    def _find_active_lists_by_name(nm):
        return [c for c in containers if c.get("workspace_id") == workspace_id and c.get("status") == "active" and c.get("type") == "list" and c.get("name") == nm]

    def _container_ancestors_map():
        # id -> parent_id
        return {c.get("id"): c.get("parent_id") for c in containers if c.get("workspace_id") == workspace_id}

    parent_map = _container_ancestors_map()

    def _find_space_for_container(container_id):
        # Walk up to the space
        cur = container_id
        seen = set()
        while cur and cur not in seen:
            seen.add(cur)
            c = next((x for x in containers if x.get("id") == cur and x.get("workspace_id") == workspace_id), None)
            if not c:
                return None
            if c.get("type") == "space":
                return c
            cur = c.get("parent_id")
        return None

    def _resolve_task_by_taskId(tid):
        matches_clickup = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("clickup_task_id") == tid]
        matches_custom = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("custom_task_id") == tid]
        t1 = matches_clickup[0] if len(matches_clickup) == 1 else None
        t2 = matches_custom[0] if len(matches_custom) == 1 else None
        if t1 and t2 and t1.get("id") != t2.get("id"):
            return _err("CONFLICT", "Ambiguous taskId: matches different tasks by clickup_task_id and custom_task_id.", taskId=tid)
        if len(matches_clickup) > 1 or len(matches_custom) > 1:
            return _err("CONFLICT", "Ambiguous taskId: multiple tasks matched.", taskId=tid)
        return t1 or t2

    def _resolve_task_by_name_in_list(tname, listname):
        lists = _find_active_lists_by_name(listname)
        if not lists:
            return _err("NOT_FOUND", "Source list not found.", sourceListName=listname)
        if len(lists) > 1:
            return _err("CONFLICT", "Ambiguous sourceListName: multiple lists match.", sourceListName=listname, matches=[c.get("id") for c in lists])
        lid = lists[0].get("id")
        matches = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("list_container_id") == lid and t.get("name") == tname]
        if not matches:
            return _err("NOT_FOUND", "Task not found in source list.", taskName=tname, sourceListName=listname)
        if len(matches) > 1:
            return _err("CONFLICT", "Ambiguous taskName in source list: multiple tasks match.", taskName=tname, sourceListName=listname, matches=[t.get("id") for t in matches])
        return matches[0]

    # Resolve destination list
    dest_list = None
    if listId is not None:
        dest_list = _find_active_list_by_id(listId)
        if not dest_list:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Destination list not found.", listId=listId)
    else:
        dests = _find_active_lists_by_name(listName)
        if not dests:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Destination list not found.", listName=listName)
        if len(dests) > 1:
            _log("error", None, {"code": "CONFLICT"})
            return _err("CONFLICT", "Ambiguous destination listName: multiple lists match.", listName=listName, matches=[c.get("id") for c in dests])
        dest_list = dests[0]

    # Resolve task
    task = None
    if taskId is not None:
        resolved = _resolve_task_by_taskId(taskId)
        if isinstance(resolved, dict) and resolved.get("error"):
            _log("error", None, {"code": resolved["error"]["code"]})
            return resolved
        task = resolved
        if not task:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Task not found.", taskId=taskId)
    else:
        resolved = _resolve_task_by_name_in_list(taskName, sourceListName)
        if isinstance(resolved, dict) and resolved.get("error"):
            _log("error", None, {"code": resolved["error"]["code"]})
            return resolved
        task = resolved

    # Validate current list exists and is list type (constraint)
    src_list = _find_active_list_by_id(task.get("list_container_id"))
    if not src_list:
        _log("error", None, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Source list container not found or inactive for this task.", taskInternalId=task.get("id"))

    # If moving to same list, idempotent: still apply status_name adjustment rule? No change, so keep.
    changed = False
    if task.get("list_container_id") != dest_list.get("id"):
        task["list_container_id"] = dest_list.get("id")
        changed = True
        # Workflow not modeled: reset status_name to null (or destination default). We'll set to null.
        if task.get("status_name") is not None:
            task["status_name"] = None
        task["updated_at"] = now

    if not changed:
        # No success without effect: but move to same list is effectively no-op; treat as idempotent success only if truly already in destination.
        # Here, requested move has no effect; real APIs often return the task. We'll allow success with explicit indicator.
        _log("ok", None, {"idempotent": True})
        return {"task": task, "idempotent": True}

    # Persist tasks
    updated = False
    for i, t in enumerate(tasks):
        if t.get("id") == task.get("id"):
            tasks[i] = task
            updated = True
            break
    if not updated:
        _log("error", None, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Task not found for update.", taskInternalId=task.get("id"))
    _save("tasks.json", tasks)

    _log("ok", None, {"moved_task_id": task.get("id"), "dest_list_id": dest_list.get("id")})
    return {"task": task}

