        return [c for c in containers if c.get("workspace_id") == workspace_id and c.get("status") == "active" and c.get("type") == "list" and c.get("name") == nm]

    def _resolve_task_by_taskId(tid):
        matches_clickup = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("clickup_task_id") == tid]
        matches_custom = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("custom_task_id") == tid]
        t1 = matches_clickup[0] if len(matches_clickup) == 1 else None
        t2 = matches_custom[0] if len(matches_custom) == 1 else None
        if t1 and t2 and t1.get("id") != t2.get("id"):
            return _err("CONFLICT", "Ambiguous taskId: matches different tasks by clickup_task_id and custom_task_id.", taskId=tid)
        if len(matches_clickup) > 1 or len(matches_custom) > 1:
            return _err("CONFLICT", "Ambiguous taskId: multiple tasks matched.", taskId=tid)
        return t1 or t2

    def _resolve_task_by_name_in_list(tname, listname):
        lists = _find_active_lists_by_name(listname)
        if not lists:
            return _err("NOT_FOUND", "Source list not found.", sourceListName=listname)
        if len(lists) > 1:
            return _err("CONFLICT", "Ambiguous sourceListName: multiple lists match.", sourceListName=listname, matches=[c.get("id") for c in lists])
        lid = lists[0].get("id")
        matches = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("list_container_id") == lid and t.get("name") == tname]
        if not matches:
            return _err("NOT_FOUND", "Task not found in source list.", taskName=tname, sourceListName=listname)
        if len(matches) > 1:
            return _err("CONFLICT", "Ambiguous taskName in source list: multiple tasks match.", taskName=tname, sourceListName=listname, matches=[t.get("id") for t in matches])
        return matches[0]

    # Resolve source task
    if taskId is not None:
        resolved = _resolve_task_by_taskId(taskId)
        if isinstance(resolved, dict) and resolved.get("error"):
            _log("error", None, {"code": resolved["error"]["code"]})
            return resolved
        src_task = resolved
        if not src_task:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Task not found.", taskId=taskId)
    else:
        resolved = _resolve_task_by_name_in_list(taskName, sourceListName)
        if isinstance(resolved, dict) and resolved.get("error"):
            _log("error", None, {"code": resolved["error"]["code"]})
            return resolved
        src_task = resolved

    # Resolve destination list (optional; defaults to original list)
    dest_list = None
    if listId is not None:
        dest_list = _find_active_list_by_id(listId)
        if not dest_list:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Destination list not found.", listId=listId)
    elif listName is not None:
        dests = _find_active_lists_by_name(listName)
        if not dests:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Destination list not found.", listName=listName)
        if len(dests) > 1:
            _log("error", None, {"code": "CONFLICT"})
            return _err("CONFLICT", "Ambiguous destination listName: multiple lists match.", listName=listName, matches=[c.get("id") for c in dests])
        dest_list = dests[0]
    else:
        dest_list = _find_active_list_by_id(src_task.get("list_container_id"))
        if not dest_list:
            _log("error", None, {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Source list container not found or inactive for this task.", taskInternalId=src_task.get("id"))

    # Generate ids
    def _new_id(prefix):
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % int((time.time() % 1) * 1_000_000))
    new_task_id = _new_id("cu_tsk_")

    # Ensure uniqueness constraints for clickup_task_id and custom_task_id: create new clickup_task_id
    existing_clickup_ids = {t.get("clickup_task_id") for t in tasks if t.get("workspace_id") == workspace_id}
    new_clickup_task_id = _new_id("dup_").upper()
    # If collision (very unlikely), loop a few times
    for _ in range(5):
        if new_clickup_task_id not in existing_clickup_ids:
            break
        new_clickup_task_id = _new_id("dup_").upper()
    if new_clickup_task_id in existing_clickup_ids:
        _log("error", None, {"code": "CONFLICT"})
        return _err("CONFLICT", "Unable to generate unique clickup_task_id for duplicated task.")

    new_task = {
        "id": new_task_id,
        "workspace_id": workspace_id,
        "list_container_id": dest_list.get("id"),
        "parent_task_id": None,  # duplicate as a top-level task unless vendor says otherwise
        "clickup_task_id": new_clickup_task_id,
        "custom_task_id": None,
        "name": src_task.get("name"),
        "description": src_task.get("description"),
        "status_name": src_task.get("status_name"),
        "priority": src_task.get("priority"),
        "start_date": src_task.get("start_date"),
        "due_date": src_task.get("due_date"),
        "time_estimate_ms": src_task.get("time_estimate_ms"),
        "assignee_clickup_user_ids": list(src_task.get("assignee_clickup_user_ids") or []),
        "custom_fields": list(src_task.get("custom_fields") or []),
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Validate required constraints for new task
    if not isinstance(new_task["name"], str) or new_task["name"].strip() == "":
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Task name cannot be empty.")
    pr = new_task.get("priority")
    if pr is not None and (not isinstance(pr, int) or pr < 0 or pr > 4):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority must be an integer 0..4 or null.", field="priority")
    te = new_task.get("time_estimate_ms")
    if te is not None and (not isinstance(te, int) or te < 0):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "time_estimate_ms must be >= 0 or null.", field="time_estimate_ms")

    # Persist new task
    tasks.append(new_task)
    _save("tasks.json", tasks)

    # Copy tag associations only (task_activity kind='task_tag'); do not copy comments/attachments/time entries
    src_task_tags = [a for a in activity if a.get("workspace_id") == workspace_id and a.get("status") == "active" and a.get("kind") == "task_tag" and a.get("task_id") == src_task.get("id")]
    # Ensure tags exist in destination task's space via existing space_tag rows; if missing, skip? Rule says "duplicate ... and tag associations ... into new rows"
    # We'll copy as-is (these are assignments), assuming space catalog already exists; if not, still create assignment rows (datastore constraint doesn't forbid).
    for a in src_task_tags:
        new_act = dict(a)
        new_act["id"] = _new_id("cu_act_")
        new_act["task_id"] = new_task_id
        new_act["clickup_id"] = None
        new_act["created_at"] = now
        new_act["updated_at"] = now
        new_act["status"] = "active"
        activity.append(new_act)
    if src_task_tags:
        _save("task_activity.json", activity)

    _log("ok", None, {"new_task_id": new_task_id, "source_task_id": src_task.get("id")})
    return {"task": new_task}

def delete_task(taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_task"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    if taskId is None and taskName is None:
        e = _err("VALIDATION_ERROR", "Provide either taskId or taskName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskId is not None and (not isinstance(taskId, str) or not taskId.strip()):
        e = _err("VALIDATION_ERROR", "taskId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        e = _err("VALIDATION_ERROR", "taskName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        e = _err("VALIDATION_ERROR", "listName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    tasks = _load("tasks.json")
    containers = _load("containers.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(containers, list):
        containers = []
    if not isinstance(activity, list):
        activity = []

    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("id")}

    def _resolve_task():
        # returns (task_row, err) ; uses ambiguity rules
        if taskId is not None:
            tid = taskId.strip()
            clickup_matches = []
            custom_matches = []
            internal_matches = []
            for t in tasks:
                if not isinstance(t, dict):
                    continue
                if t.get("status") != "active":
                    continue
                if t.get("clickup_task_id") == tid:
                    clickup_matches.append(t)
                if t.get("custom_task_id") and t.get("custom_task_id") == tid:
                    custom_matches.append(t)
                if t.get("id") == tid:
                    internal_matches.append(t)
            # if internal id matches and differs from others, still could be ambiguous
            ids = {x.get("id") for x in (clickup_matches + custom_matches + internal_matches) if x.get("id")}
            if len(ids) == 0:
                return None, _err("NOT_FOUND", "task not found", taskId=tid)
            if len(ids) > 1:
                return None, _err("CONFLICT", "taskId is ambiguous (matched multiple tasks via clickup_task_id/custom_task_id).", taskId=tid, matches=len(ids))
            return (clickup_matches + custom_matches + internal_matches)[0], None

        # taskName resolution (must fail if multiple active matches exist when insufficient scope)
        tn = taskName.strip()
        if listName is not None:
            ln = listName.strip()
            list_candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == ln]
            if len(list_candidates) == 0:
                return None, _err("NOT_FOUND", "list not found for listName scope", listName=ln)
            if len(list_candidates) > 1:
                return None, _err("CONFLICT", "listName is ambiguous; cannot resolve taskName.", listName=ln, matches=len(list_candidates))
            list_id = list_candidates[0].get("id")
            hits = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("list_container_id") == list_id and t.get("name") == tn]
            if len(hits) == 0:
                return None, _err("NOT_FOUND", "task not found", taskName=tn, listName=ln)
            if len(hits) > 1:
                return None, _err("CONFLICT", "taskName is ambiguous within listName scope.", taskName=tn, listName=ln, matches=len(hits))
            return hits[0], None
        else:
            hits = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("name") == tn]
            if len(hits) == 0:
                return None, _err("NOT_FOUND", "task not found", taskName=tn)
            if len(hits) > 1:
                return None, _err("CONFLICT", "taskName is ambiguous within workspace (no listName provided).", taskName=tn, matches=len(hits))
            return hits[0], None

    task, err = _resolve_task()
    if err:
        _log("error", err["error"]["code"])
        return err

    now = _now()
    if task.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Task is not active and cannot be deleted.", taskId=task.get("id"), status=task.get("status"))
        _log("error", "INVALID_TRANSITION")
        return e

    # mutate tasks row
    affected_task = 0
    for t in tasks:
        if isinstance(t, dict) and t.get("id") == task.get("id"):
            t["status"] = "deleted"
            t["updated_at"] = now
            affected_task = 1
            break
    if affected_task != 1:
        e = _err("NOT_FOUND", "Task disappeared during deletion.", taskId=task.get("id"))
        _log("error", "NOT_FOUND")
        return e

    # also soft-delete related activity rows
    affected_activity = 0
    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("task_id") == task.get("id") and a.get("status") == "active":
            a["status"] = "deleted"
            a["updated_at"] = now
            affected_activity += 1

    _save("tasks.json", tasks)
    _save("task_activity.json", activity)

    _log("ok", meta={"task_id": task.get("id"), "deleted_activity_rows": affected_activity})
    return {"task_id": task.get("id"), "status": "deleted", "deleted_activity_rows": affected_activity}

def get_task_comments(taskId=None, taskName=None, listName=None, start=None, startId=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, details=None):
        fname = "request_log.json"
        if not os.path.exists(os.path.join(_DB, fname)):
            return
        rows = _load(fname)
        rid = "cu_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % int((time.time() % 1) * 1_000_000))
        rows.append({
            "id": rid,
            "endpoint": "get_task_comments",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": now,
            "details": details or {}
        })
        _save(fname, rows)

    workspaces = _load("workspaces.json")
    workspace = next((w for w in workspaces if w.get("status") == "active"), None)
    if not workspace:
        _log("error", None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active workspace available to serve this request.")
    workspace_id = workspace.get("id")

    if not isinstance(taskId, (str, type(None))) or not isinstance(taskName, (str, type(None))) or not isinstance(listName, (str, type(None))) or not isinstance(start, (int, type(None))) or not isinstance(startId, (str, type(None))):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid parameter types.")
    if taskId is None and taskName is None:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Provide either taskId or taskName.")
    if start is not None and start < 0:
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start must be >= 0.", field="start")
    if startId is not None and not re.match(r"^cu_act_[0-9A-Z]{18,}$", startId):
        _log("error", None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "startId format is invalid.", field="startId")

    containers = _load("containers.json")
    tasks = _load("tasks.json")
    activity = _load("task_activity.json")

    def _find_active_lists_by_name(nm):
        return [c for c in containers if c.get("workspace_id") == workspace_id and c.get("status") == "active" and c.get("type") == "list" and c.get("name") == nm]

    def _resolve_task_by_taskId(tid):
        matches_clickup = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("clickup_task_id") == tid]
        matches_custom = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("custom_task_id") == tid]
        t1 = matches_clickup[0] if len(matches_clickup) == 1 else None
        t2 = matches_custom[0] if len(matches_custom) == 1 else None
        if t1 and t2 and t1.get("id") != t2.get("id"):
            return _err("CONFLICT", "Ambiguous taskId: matches different tasks by clickup_task_id and custom_task_id.", taskId=tid)
        if len(matches_clickup) > 1 or len(matches_custom) > 1:
            return _err("CONFLICT", "Ambiguous taskId: multiple tasks matched.", taskId=tid)
        return t1 or t2

    def _resolve_task_by_name(tname, maybe_listname):
        candidates = [t for t in tasks if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("name") == tname]
        if maybe_listname is not None:
            lists = _find_active_lists_by_name(maybe_listname)
            if not lists:
                return _err("NOT_FOUND", "List not found.", listName=maybe_listname)
            if len(lists) > 1:
                return _err("CONFLICT", "Ambiguous listName: multiple lists match.", listName=maybe_listname, matches=[c.get("id") for c in lists])
            lid = lists[0].get("id")
            candidates = [t for t in candidates if t.get("list_container_id") == lid]
        if not candidates:
            return None
        if len(candidates) > 1:
            return _err("CONFLICT", "Ambiguous taskName: multiple tasks match.", taskName=tname, listName=maybe_listname, matches=[t.get("id") for t in candidates])
        return candidates[0]

    # Resolve task
    task = None
    if taskId is not None:
        resolved = _resolve_task_by_taskId(taskId)
        if isinstance(resolved, dict) and resolved.get("error"):
            _log("error", None, {"code": resolved["error"]["code"]})
            return resolved
        task = resolved
        if not task:
            _log("ok", None, {"empty": True})
            return {"comments": [], "task": None, "pagination": {"total": 0, "has_more": False, "next_start": None, "next_startId": None}}
    else:
        resolved = _resolve_task_by_name(taskName, listName)
        if isinstance(resolved, dict) and resolved.get("error"):
            _log("error", None, {"code": resolved["error"]["code"]})
            return resolved
        task = resolved
        if not task:
            _log("ok", None, {"empty": True})
            return {"comments": [], "task": None, "pagination": {"total": 0, "has_more": False, "next_start": None, "next_startId": None}}

    # Filter comments
    comments = [a for a in activity
                if a.get("workspace_id") == workspace_id
                and a.get("status") == "active"
                and a.get("kind") == "comment"
                and a.get("task_id") == task.get("id")]

    # Order by created_at asc, then id
    def _key(a):
        return (a.get("created_at") or "", a.get("id") or "")
    comments.sort(key=_key)

    # Cursor pagination: start/startId represent "start after (created_at, id)" semantics; start is treated as offset fallback.
    if startId is not None:
        # find the startId row to determine its created_at; if not found, treat as starting from beginning (vendor behavior varies)
        anchor = next((c for c in comments if c.get("id") == startId), None)
        if anchor is not None:
            ak = _key(anchor)
            comments = [c for c in comments if _key(c) > ak]
        # if anchor missing, do not error; return from beginning/offset
    if start is not None and start > 0:
        if start < len(comments):
            comments = comments[start:]
        else:
            comments = []

    page_size = 50
    page = comments[:page_size]
    has_more = len(comments) > page_size
    next_start = None
    next_startId = None
    if has_more and page:
        next_start = (start or 0) + page_size
        next_startId = page[-1].get("id")

    _log("ok", None, {"task_id": task.get("id"), "returned": len(page), "has_more": has_more})
    return {
        "task": {"id": task.get("id"), "clickup_task_id": task.get("clickup_task_id"), "custom_task_id": task.get("custom_task_id"), "name": task.get("name")},
        "comments": page,
        "pagination": {
            "total": len([a for a in activity if a.get("workspace_id") == workspace_id and a.get("status") == "active" and a.get("kind") == "comment" and a.get("task_id") == task.get("id")]),
            "has_more": has_more,
            "next_start": next_start,
            "next_startId": next_startId
        }
    }

def create_task_comment(commentText, taskId=None, taskName=None, listName=None, notifyAll=None, assignee=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_task_comment"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}{''.join(secrets.choice(alphabet) for _ in range(22))}"

    if not isinstance(commentText, str) or not commentText.strip():
        e = _err("VALIDATION_ERROR", "commentText must be a non-empty string.", rule="kind='comment' implies task_id is not null and body_text is not null and body_text <> ''")
        _log("error", "VALIDATION_ERROR")
        return e
    body = commentText.strip()

    if notifyAll is not None and not isinstance(notifyAll, bool):
        e = _err("VALIDATION_ERROR", "notifyAll must be a boolean when provided.")
