def attach_task_file(sourceType, taskId=None, taskName=None, listName=None, filename=None, base64=None, url=None, localPath=None, chunked=None, **_extra):
    import json, os, datetime, time, secrets, base64 as b64mod, urllib.parse, binascii

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "attach_task_file"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}{''.join(secrets.choice(alphabet) for _ in range(22))}"

    if not isinstance(sourceType, str) or sourceType not in ("base64", "url", "local_path", "chunked"):
        e = _err("VALIDATION_ERROR", "sourceType must be one of: base64, url, local_path, chunked.")
        _log("error", "VALIDATION_ERROR")
        return e

    if taskId is None and taskName is None:
        e = _err("VALIDATION_ERROR", "Provide taskId or taskName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskId is not None and (not isinstance(taskId, str) or not taskId.strip()):
        e = _err("VALIDATION_ERROR", "taskId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        e = _err("VALIDATION_ERROR", "taskName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        e = _err("VALIDATION_ERROR", "listName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if filename is not None and (not isinstance(filename, str) or not filename.strip()):
        e = _err("VALIDATION_ERROR", "filename must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    # Validate source-specific fields
    attachment_size = None
    attachment_url = None
    attachment_filename = filename.strip() if isinstance(filename, str) and filename.strip() else None

    if sourceType == "base64":
        if attachment_filename is None:
            e = _err("VALIDATION_ERROR", "filename is required when sourceType=base64.")
            _log("error", "VALIDATION_ERROR")
            return e
        if base64 is None or not isinstance(base64, str) or not base64.strip():
            e = _err("VALIDATION_ERROR", "base64 is required when sourceType=base64.")
            _log("error", "VALIDATION_ERROR")
            return e
        try:
            raw = b64mod.b64decode(base64.strip(), validate=True)
        except (binascii.Error, ValueError):
            e = _err("VALIDATION_ERROR", "base64 must be valid base64 data.")
            _log("error", "VALIDATION_ERROR")
            return e
        attachment_size = len(raw)
        if attachment_size > 10485760:
            e = _err("VALIDATION_ERROR", "base64 attachment exceeds 10MB limit.", rule="attachment_size_bytes <= 10485760 when attachment_source_type='base64'", attachment_size_bytes=attachment_size)
            _log("error", "VALIDATION_ERROR")
            return e
        # In real service, file would be stored and URL returned; offline, we omit URL.
    elif sourceType == "url":
        if url is None or not isinstance(url, str) or not url.strip():
            e = _err("VALIDATION_ERROR", "url is required when sourceType=url.")
            _log("error", "VALIDATION_ERROR")
            return e
        parsed = urllib.parse.urlparse(url.strip())
        if parsed.scheme not in ("http", "https") or not parsed.netloc:
            e = _err("VALIDATION_ERROR", "url must be a valid http/https URL when sourceType=url.")
            _log("error", "VALIDATION_ERROR")
            return e
        attachment_url = url.strip()
        if attachment_filename is None:
            # best-effort derive filename from URL path
            base = os.path.basename(parsed.path)
            attachment_filename = base if base else None
    elif sourceType == "local_path":
        if localPath is None or not isinstance(localPath, str) or not localPath.strip():
            e = _err("VALIDATION_ERROR", "localPath is required when sourceType=local_path.")
            _log("error", "VALIDATION_ERROR")
            return e
        lp = localPath.strip()
        if not os.path.isabs(lp):
            e = _err("VALIDATION_ERROR", "localPath must be an absolute path when sourceType=local_path.")
            _log("error", "VALIDATION_ERROR")
            return e
        if attachment_filename is None:
            attachment_filename = os.path.basename(lp) or None
        # offline: we do not read file; size/url unknown
    elif sourceType == "chunked":
        if chunked is None or not isinstance(chunked, dict) or not isinstance(chunked.get("uploadId"), str) or not chunked.get("uploadId").strip():
            e = _err("VALIDATION_ERROR", "chunked.uploadId is required when sourceType=chunked.")
            _log("error", "VALIDATION_ERROR")
            return e
        # Accept other fields; offline we do not assemble; treat as accepted metadata.

    tasks = _load("tasks.json")
    containers = _load("containers.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(containers, list):
        containers = []
    if not isinstance(activity, list):
        activity = []

    def _resolve_task():
        if taskId is not None:
