def update_bulk_tasks(tasks, options=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status, error=None, meta=None):
        logs = _load("request_log.json")
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}",
            "service": "clickup_mcp",
            "endpoint": "update_bulk_tasks",
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "error": error,
            "meta": meta or {}
        })
        _save("request_log.json", logs)

    if not isinstance(tasks, list) or len(tasks) < 1:
        e = _err("VALIDATION_ERROR", "tasks must be a non-empty array.")
        _log("error", e["error"])
        return e

    if options is not None and not isinstance(options, dict):
        e = _err("VALIDATION_ERROR", "options must be an object when provided.")
        _log("error", e["error"])
        return e
    if isinstance(options, dict):
        if "batchSize" in options and (not isinstance(options["batchSize"], int) or options["batchSize"] < 1):
            e = _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1.")
            _log("error", e["error"])
            return e
        if "concurrency" in options and (not isinstance(options["concurrency"], int) or options["concurrency"] < 1):
            e = _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1.")
            _log("error", e["error"])
            return e

    workspaces = _load("workspaces.json")
    members = _load("members.json")
    containers = _load("containers.json")
    tasks_store = _load("tasks.json")

    active_workspaces = [w for w in workspaces if w.get("status") == "active"]
    if not active_workspaces:
        e = _err("UNAUTHORIZED", "No active workspace available to serve the request.")
        _log("error", e["error"])
        return e

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string when provided.")
        try:
            ss = s.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(microsecond=0).isoformat() + "Z"
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string.", value=s)

    def _resolve_member_ids(wsid, assignees_list):
        if assignees_list is None:
            return None
        if not isinstance(assignees_list, list) or any(not isinstance(x, str) for x in assignees_list):
            return _err("VALIDATION_ERROR", "assignees must be an array of strings when provided.")
        out = []
        for a in assignees_list:
            s = a.strip()
            if not s:
                return _err("VALIDATION_ERROR", "assignees entries must be non-empty strings.")
            cand = []
            for m in members:
                if m.get("workspace_id") != wsid or m.get("status") != "active":
                    continue
                if m.get("clickup_user_id") == s:
                    cand.append(m); continue
                if m.get("email") and m.get("email") == s:
                    cand.append(m); continue
                if m.get("username") and m.get("username") == s:
                    cand.append(m); continue
                if m.get("full_name") and m.get("full_name") == s:
                    cand.append(m); continue
            if len(cand) == 1:
                out.append(cand[0].get("clickup_user_id"))
            elif len(cand) > 1:
                return _err("CONFLICT", "Assignee identifier is ambiguous in workspace.", assignee=a, matches=len(cand))
            else:
                return _err("NOT_FOUND", "Assignee not found in workspace members.", assignee=a)
        # de-dupe preserving order
        dedup = []
        seen = set()
        for x in out:
            if x not in seen:
                seen.add(x)
                dedup.append(x)
        return dedup

    def _resolve_list_by_name(workspace_id, lname):
        m = [c for c in containers if c.get("workspace_id") == workspace_id and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == lname]
        if len(m) == 1:
            return m[0]
        if len(m) > 1:
            return _err("CONFLICT", "listName is ambiguous within workspace.", listName=lname, matches=len(m))
        return None

    def _resolve_task_by_taskId_or_custom(workspace_id, tid_value):
        matches_clickup = [t for t in tasks_store if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("clickup_task_id") == tid_value]
        matches_custom = [t for t in tasks_store if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("custom_task_id") == tid_value]
        ids_clickup = {t["id"] for t in matches_clickup}
        ids_custom = {t["id"] for t in matches_custom}
        if ids_clickup and ids_custom and ids_clickup != ids_custom:
            return _err("CONFLICT", "taskId is ambiguous: it matches both clickup_task_id and custom_task_id on different tasks.", taskId=tid_value)
        allm = matches_clickup if ids_clickup else matches_custom
        if not allm:
            return None
        if len(allm) > 1:
            return _err("CONFLICT", "taskId resolution returned multiple tasks.", taskId=tid_value)
        return allm[0]

    def _resolve_task_by_name(workspace_id, tname, lname):
        # For update_bulk_tasks: taskName without listName will fail.
        if lname is None:
            return _err("VALIDATION_ERROR", "listName is required when resolving by taskName for bulk updates.")
        lst = _resolve_list_by_name(workspace_id, lname)
        if isinstance(lst, dict) and "error" in lst:
            return lst
        if lst is None:
            return _err("NOT_FOUND", "listName not found in workspace.", listName=lname)
        cand = [t for t in tasks_store if t.get("workspace_id") == workspace_id and t.get("status") == "active" and t.get("name") == tname and t.get("list_container_id") == lst.get("id")]
        if len(cand) == 1:
            return cand[0]
        if len(cand) == 0:
            return None
        return _err("CONFLICT", "taskName+listName is ambiguous; multiple active matches.", taskName=tname, listName=lname, matches=len(cand))

    # Validate each instruction has at least one update field
    mutable_fields = {"name", "description", "status", "priority", "startDate", "dueDate", "timeEstimateMs", "assignees", "customFields"}
    for i, inst in enumerate(tasks):
        if not isinstance(inst, dict):
            e = _err("VALIDATION_ERROR", "Each tasks[] entry must be an object.", index=i)
            _log("error", e["error"])
            return e
        if inst.get("taskId") is None and inst.get("taskName") is None:
            e = _err("VALIDATION_ERROR", "Each update must include taskId or taskName+listName.", index=i)
            _log("error", e["error"])
            return e
        if inst.get("taskName") is not None and (inst.get("listName") is None or not isinstance(inst.get("listName"), str) or not inst.get("listName").strip()):
            e = _err("VALIDATION_ERROR", "listName is required when using taskName for bulk updates.", index=i)
            _log("error", e["error"])
            return e
        if inst.get("taskId") is not None:
            if not isinstance(inst.get("taskId"), str) or re.match(r"^cu_tsk_[0-9A-Z]{18,}$", inst["taskId"]) is None:
                e = _err("VALIDATION_ERROR", "taskId must match pattern ^cu_tsk_[0-9A-Z]{18,}$.", index=i)
                _log("error", e["error"])
                return e
        if inst.get("priority") is not None:
            if not isinstance(inst.get("priority"), int) or not (0 <= inst["priority"] <= 4):
                e = _err("VALIDATION_ERROR", "priority must be integer 0..4 when provided.", index=i)
                _log("error", e["error"])
                return e
        if inst.get("timeEstimateMs") is not None:
            if not isinstance(inst.get("timeEstimateMs"), int) or inst["timeEstimateMs"] < 0:
                e = _err("VALIDATION_ERROR", "timeEstimateMs must be integer >= 0 when provided.", index=i)
                _log("error", e["error"])
                return e
        if inst.get("customFields") is not None:
            if not isinstance(inst.get("customFields"), list):
                e = _err("VALIDATION_ERROR", "customFields must be an array when provided.", index=i)
                _log("error", e["error"])
                return e
            for j, cf in enumerate(inst["customFields"]):
                if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or not isinstance(cf["id"], str) or not cf["id"].strip():
                    e = _err("VALIDATION_ERROR", "Each customFields entry must be {id, value} with non-empty string id.", index=i, customFieldIndex=j)
                    _log("error", e["error"])
                    return e
        if inst.get("assignees") is not None and (not isinstance(inst.get("assignees"), list) or any(not isinstance(x, str) for x in inst["assignees"])):
            e = _err("VALIDATION_ERROR", "assignees must be an array of strings when provided.", index=i)
            _log("error", e["error"])
            return e

        if not any(k in inst for k in mutable_fields):
            e = _err("VALIDATION_ERROR", "Each update must include at least one update field.", index=i)
            _log("error", e["error"])
            return e

    per_item = []
    updated_rows = []
    any_updated = False

    for i, inst in enumerate(tasks):
        try:
            # Find candidate across all active workspaces, choosing one that resolves.
            resolved_task = None
            resolved_ws = None
            resolution_error = None
            for ws in active_workspaces:
                wsid = ws["id"]
                if inst.get("taskId") is not None:
                    r = _resolve_task_by_taskId_or_custom(wsid, inst["taskId"])
                    if isinstance(r, dict) and "error" in r:
                        resolution_error = r
                        break
                    if r is not None:
                        resolved_task = r
                        resolved_ws = ws
                        break
                else:
                    r = _resolve_task_by_name(wsid, inst.get("taskName"), inst.get("listName"))
                    if isinstance(r, dict) and "error" in r:
                        resolution_error = r
                        break
                    if r is not None:
                        resolved_task = r
                        resolved_ws = ws
                        break

            if resolution_error is not None:
                per_item.append({"index": i, "ok": False, "error": resolution_error["error"]})
                continue
            if resolved_task is None or resolved_ws is None:
                per_item.append({"index": i, "ok": False, "error": {"code": "NOT_FOUND", "message": "Task not found."}})
                continue

            wsid = resolved_ws["id"]

            # Apply changes; enforce "update_task requires at least one mutable field change"
            changes = {}
            if "name" in inst:
                if inst["name"] is not None and (not isinstance(inst["name"], str) or not inst["name"].strip()):
                    per_item.append({"index": i, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "name must be a non-empty string when provided."}})
                    continue
                changes["name"] = inst["name"].strip() if isinstance(inst["name"], str) else None
            if "description" in inst:
                if inst["description"] is not None and not isinstance(inst["description"], str):
                    per_item.append({"index": i, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "description must be a string or null."}})
                    continue
                changes["description"] = inst["description"]
            if "status" in inst:
                if inst["status"] is not None and (not isinstance(inst["status"], str) or not inst["status"].strip()):
                    per_item.append({"index": i, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "status must be a non-empty string when provided."}})
                    continue
                changes["status_name"] = inst["status"].strip() if isinstance(inst["status"], str) else None
            if "priority" in inst:
                changes["priority"] = inst["priority"]
            if "startDate" in inst:
                sd = _parse_dt(inst.get("startDate"), "startDate")
                if isinstance(sd, dict) and "error" in sd:
                    per_item.append({"index": i, "ok": False, "error": sd["error"]})
                    continue
                changes["start_date"] = sd
            if "dueDate" in inst:
                dd = _parse_dt(inst.get("dueDate"), "dueDate")
                if isinstance(dd, dict) and "error" in dd:
                    per_item.append({"index": i, "ok": False, "error": dd["error"]})
                    continue
                changes["due_date"] = dd
            if "timeEstimateMs" in inst:
                changes["time_estimate_ms"] = inst.get("timeEstimateMs")
            if "assignees" in inst:
                mids = _resolve_member_ids(wsid, inst.get("assignees"))
                if isinstance(mids, dict) and "error" in mids:
                    per_item.append({"index": i, "ok": False, "error": mids["error"]})
                    continue
                changes["assignee_clickup_user_ids"] = mids if mids is not None else []
            if "customFields" in inst:
                changes["custom_fields"] = inst.get("customFields") if isinstance(inst.get("customFields"), list) else []

            # Determine if changes actually differ
            real_changes = {}
            for k, v in changes.items():
                if resolved_task.get(k) != v:
                    real_changes[k] = v

            if not real_changes:
                per_item.append({"index": i, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "No changes provided (fields are identical to existing values)."}})
                continue

            # Enforce constraints: name <> ''
            if "name" in real_changes and (real_changes["name"] is None or not str(real_changes["name"]).strip()):
                per_item.append({"index": i, "ok": False, "error": {"code": "VALIDATION_ERROR", "message": "Task name must be non-empty."}})
                continue

            # Apply update in store (in-place)
            for trow in tasks_store:
                if trow.get("id") == resolved_task.get("id"):
                    for k, v in real_changes.items():
                        trow[k] = v
                    trow["updated_at"] = _now()
                    updated_rows.append(trow)
                    any_updated = True
                    per_item.append({"index": i, "ok": True, "task": trow, "changed": sorted(list(real_changes.keys()))})
                    break
            else:
                per_item.append({"index": i, "ok": False, "error": {"code": "NOT_FOUND", "message": "Task not found for update."}})
        except Exception:
            per_item.append({"index": i, "ok": False, "error": {"code": "CONFLICT", "message": "Unexpected failure while updating task."}})

    if any_updated:
        _save("tasks.json", tasks_store)

    if not any_updated:
        e = _err("NOT_FOUND", "No tasks were updated.", results=per_item)
        _log("error", e["error"])
        return e

    out = {
        "updated": updated_rows,
        "results": per_item,
        "meta": {"requested": len(tasks), "updated": len([r for r in per_item if r.get("ok")])}
    }
    _log("ok", meta={"requested": len(tasks), "updated": out["meta"]["updated"]})
    return out

def move_bulk_tasks(tasks, targetListId=None, targetListName=None, options=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # --- request log / rate limit (best-effort, offline) ---
    def _log(status, credential_id=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "move_bulk_tasks",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_log.json", logs)

    # Basic global rate limit: 120 req/min across store
    logs_rl = _load("request_log.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl[-2000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                recent += 1
    if recent >= 120:
        _log("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # --- validation ---
    if not isinstance(tasks, list) or len(tasks) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array")
    if options is not None and not isinstance(options, dict):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "options must be an object when provided")

    batch_size = None
    concurrency = None
    if isinstance(options, dict):
        if "batchSize" in options:
            batch_size = options.get("batchSize")
            if not isinstance(batch_size, int) or batch_size < 1:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1")
        if "concurrency" in options:
            concurrency = options.get("concurrency")
            if not isinstance(concurrency, int) or concurrency < 1:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1")

    cu_cnt_re = re.compile(r"^cu_cnt_[0-9A-Z]{18,}$")
    cu_tsk_re = re.compile(r"^cu_tsk_[0-9A-Z]{18,}$")

    if targetListId is not None:
        if not isinstance(targetListId, str) or not cu_cnt_re.match(targetListId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "targetListId must match ^cu_cnt_[0-9A-Z]{18,}$")
    if targetListName is not None and (not isinstance(targetListName, str) or targetListName.strip() == ""):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "targetListName must be a non-empty string when provided")

    # each item must have taskId OR (taskName + listName)
    for i, it in enumerate(tasks):
        if not isinstance(it, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"tasks[{i}] must be an object")
        tid = it.get("taskId")
        tname = it.get("taskName")
        lname = it.get("listName")
        if tid is None:
            if not (isinstance(tname, str) and tname.strip() and isinstance(lname, str) and lname.strip()):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"tasks[{i}] must include taskId or taskName+listName")
        else:
            if not isinstance(tid, str) or not cu_tsk_re.match(tid):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"tasks[{i}].taskId must match ^cu_tsk_[0-9A-Z]{{18,}}$")

    # --- load store ---
    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")

    if not isinstance(workspaces, list) or not isinstance(containers, list) or not isinstance(tasks_rows, list):
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unavailable")

    # --- ambient auth resolution: pick any active workspace that can satisfy request ---
    active_wsp = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
    if not active_wsp:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace available")
    # We'll resolve target list first; it implies workspace.
    def _container_by_id(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("id") == cid:
                return c
        return None

    def _active_lists_in_workspace(wsp_id):
        return [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == wsp_id and c.get("type") == "list" and c.get("status") == "active"]

    target_list = None
    target_wsp_id = None
    if targetListId is not None:
        c = _container_by_id(targetListId)
        if not c or c.get("status") != "active" or c.get("type") != "list":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Target list not found", targetListId=targetListId)
        target_list = c
        target_wsp_id = c.get("workspace_id")
    else:
        # resolve by name within any active workspace that has exactly one active list with that name
        if not isinstance(targetListName, str) or targetListName.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "targetListId or targetListName is required")
        tname = targetListName.strip()
        candidates = []
        for w in active_wsp:
            wsp_id = w.get("id")
            matches = [c for c in _active_lists_in_workspace(wsp_id) if c.get("name") == tname]
            if len(matches) == 1:
                candidates.append(matches[0])
        if not candidates:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Target list not found by name", targetListName=targetListName)
        if len(candidates) > 1:
            # ambiguous across workspaces; validation-like conflict
            _log("CONFLICT")
            return _err("CONFLICT", "Target list name is ambiguous across workspaces; use targetListId", targetListName=targetListName)
        target_list = candidates[0]
        target_wsp_id = target_list.get("workspace_id")

    # workspace must be active
    wsp_row = None
    for w in active_wsp:
        if w.get("id") == target_wsp_id:
            wsp_row = w
            break
    if not wsp_row:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace not available for operation")

    # --- helpers for item resolution ---
    def _resolve_task_by_internal_id(wsp_id, internal_task_id):
        for t in tasks_rows:
            if isinstance(t, dict) and t.get("workspace_id") == wsp_id and t.get("id") == internal_task_id and t.get("status") == "active":
                return t
        return None

    def _resolve_source_list_by_name(wsp_id, list_name):
        matches = [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == wsp_id and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == list_name]
        if len(matches) == 1:
            return matches[0]
        if len(matches) == 0:
            return None
        return "AMBIGUOUS_LIST"

    def _resolve_task_by_name_in_list(wsp_id, task_name, list_container_id):
        matches = []
        for t in tasks_rows:
            if not isinstance(t, dict):
                continue
            if t.get("workspace_id") != wsp_id or t.get("status") != "active":
                continue
            if t.get("name") == task_name and t.get("list_container_id") == list_container_id:
                matches.append(t)
        if len(matches) == 1:
            return matches[0]
        if len(matches) == 0:
            return None
        return "AMBIGUOUS_TASK"

    # --- apply moves, per-item results ---
    results = []
    updated_tasks = []
    changed_any = False

    for it in tasks:
        tid = it.get("taskId")
        tname = it.get("taskName")
        lname = it.get("listName")

        task_row = None
        err = None

        if tid is not None:
            task_row = _resolve_task_by_internal_id(target_wsp_id, tid)
            if not task_row:
                err = _err("NOT_FOUND", "Task not found", taskId=tid)
        else:
            src_list = _resolve_source_list_by_name(target_wsp_id, lname)
            if src_list is None:
                err = _err("NOT_FOUND", "Source list not found", listName=lname)
            elif src_list == "AMBIGUOUS_LIST":
                err = _err("CONFLICT", "Source list name is ambiguous; use taskId", listName=lname)
            else:
                task_row = _resolve_task_by_name_in_list(target_wsp_id, tname, src_list.get("id"))
                if task_row is None:
                    err = _err("NOT_FOUND", "Task not found by name in list", taskName=tname, listName=lname)
                elif task_row == "AMBIGUOUS_TASK":
                    err = _err("CONFLICT", "Task name is ambiguous within the source list; use taskId", taskName=tname, listName=lname)

        if err:
            results.append({"input": it, "ok": False, "error": err["error"]})
            continue

        # move_task business rule: update list_container_id; reset status_name to null (workflow not modeled)
        if task_row.get("list_container_id") == target_list.get("id"):
            # idempotent move
            results.append({"input": it, "ok": True, "task": task_row})
            updated_tasks.append(task_row)
            continue

        task_row["list_container_id"] = target_list.get("id")
        task_row["status_name"] = None
        task_row["updated_at"] = now
        changed_any = True

        results.append({"input": it, "ok": True, "task": task_row})
        updated_tasks.append(task_row)

    if changed_any:
        _save("tasks.json", tasks_rows)

    _log("OK", meta={"moved": sum(1 for r in results if r.get("ok")), "failed": sum(1 for r in results if not r.get("ok"))})
    return {
        "workspaceId": target_wsp_id,
        "targetList": {"id": target_list.get("id"), "name": target_list.get("name")},
        "results": results,
        "tasks": updated_tasks,
        "meta": {
            "total": len(tasks),
            "moved": sum(1 for r in results if r.get("ok")),
            "failed": sum(1 for r in results if not r.get("ok")),
            "batch": {"batchSize": batch_size, "concurrency": concurrency}
        }
    }

def delete_bulk_tasks(tasks, options=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_bulk_tasks"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _append_log(status, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            "meta": meta or {},
        }
        if error_code: row["error_code"] = error_code
        logs.append(row)
        _save("request_log.json", logs)

    if not isinstance(tasks, list) or len(tasks) < 1:
        e = _err("VALIDATION_ERROR", "tasks must be a non-empty array")
        _append_log("error", "VALIDATION_ERROR")
        return e
    if options is not None and not isinstance(options, dict):
        e = _err("VALIDATION_ERROR", "options must be an object when provided")
        _append_log("error", "VALIDATION_ERROR")
        return e
    if isinstance(options, dict):
        if "batchSize" in options and (not isinstance(options["batchSize"], int) or options["batchSize"] < 1):
            e = _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1")
            _append_log("error", "VALIDATION_ERROR")
            return e
        if "concurrency" in options and (not isinstance(options["concurrency"], int) or options["concurrency"] < 1):
            e = _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1")
            _append_log("error", "VALIDATION_ERROR")
            return e

    # Implement as repeated single delete (soft-delete per business rules described for delete_task)
    tasks_rows = _load("tasks.json")
    activity_rows = _load("task_activity.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(activity_rows, list): activity_rows = []

    def _soft_delete_task_by_id(internal_task_id):
        # returns (ok, payload_or_error)
        t = next((r for r in tasks_rows if isinstance(r, dict) and r.get("id") == internal_task_id), None)
        if not t:
            return False, _err("NOT_FOUND", "task not found", taskId=internal_task_id)["error"]
        if t.get("status") == "deleted":
            # idempotent
            return True, {"taskId": internal_task_id, "status": "deleted", "idempotent": True}
        # lifecycle transition active -> deleted only
        if t.get("status") != "active":
            return False, _err("INVALID_TRANSITION", "task cannot be deleted from its current status", current=t.get("status"))["error"]
        now = _now()
        t["status"] = "deleted"
        t["updated_at"] = now
        # cascade delete all related activity rows for this task
        changed = False
        for a in activity_rows:
            if isinstance(a, dict) and a.get("task_id") == internal_task_id and a.get("status") == "active":
                a["status"] = "deleted"
                a["updated_at"] = now
                changed = True
        return True, {"taskId": internal_task_id, "status": "deleted", "cascaded_activity": bool(changed)}

    def _resolve_task_by_name(taskName, listName):
        if not isinstance(taskName, str) or not taskName.strip():
            return None, _err("VALIDATION_ERROR", "taskName must be a non-empty string when provided")["error"]
        if not isinstance(listName, str) or not listName.strip():
            return None, _err("VALIDATION_ERROR", "listName is required when resolving by taskName")["error"]
        tn = taskName.strip()
        ln = listName.strip()
        containers = _load("containers.json")
        if not isinstance(containers, list): containers = []
        lists = [c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == ln]
        if len(lists) == 0:
            return None, _err("NOT_FOUND", "list not found for taskName resolution", listName=ln)["error"]
        list_ids = {c.get("id") for c in lists}
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") == "active" and t.get("name") == tn and t.get("list_container_id") in list_ids]
        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "task not found", taskName=tn, listName=ln)["error"]
        if len(candidates) > 1:
            return None, _err("CONFLICT", "taskName+listName is ambiguous; provide taskId", matches=[t.get("id") for t in candidates])["error"]
        return candidates[0], None

    results = []
    deleted_count = 0
    for idx, item in enumerate(tasks):
        if not isinstance(item, dict):
            results.append({"index": idx, "ok": False, "error": _err("VALIDATION_ERROR", "delete item must be an object")["error"]})
            continue
        tid = item.get("taskId")
        tn = item.get("taskName")
        ln = item.get("listName")

        if tid is None and tn is None:
            results.append({"index": idx, "ok": False, "error": _err("VALIDATION_ERROR", "Each item must include taskId or taskName")["error"]})
            continue

        if tid is not None:
            if not isinstance(tid, str) or not tid.strip():
                results.append({"index": idx, "ok": False, "error": _err("VALIDATION_ERROR", "taskId must be a non-empty string")["error"]})
                continue
            ok, payload = _soft_delete_task_by_id(tid.strip())
            results.append({"index": idx, "ok": ok, **({"result": payload} if ok else {"error": payload})})
            if ok and not payload.get("idempotent"):
                deleted_count += 1
        else:
            task_row, err = _resolve_task_by_name(tn, ln)
            if err:
                results.append({"index": idx, "ok": False, "error": err})
                continue
            ok, payload = _soft_delete_task_by_id(task_row.get("id"))
            results.append({"index": idx, "ok": ok, **({"result": payload} if ok else {"error": payload})})
            if ok and not payload.get("idempotent"):
                deleted_count += 1

    # Persist if anything changed (ensure "no success without effect" is handled per-item)
    _save("tasks.json", tasks_rows)
    _save("task_activity.json", activity_rows)

    _append_log("ok", meta={"deleted_count": deleted_count, "requested_count": len(tasks)})
    return {"results": results}

def get_workspace_tasks(workspaceId, tags=None, list_ids=None, folder_ids=None, space_ids=None, statuses=None, assignee_clickup_user_ids=None, subtasks=None, archived=None, due_after=None, due_before=None, updated_after=None, sort=None, sort_dir=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get_workspace_tasks",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            "meta": meta or {}
        })
        _save("request_log.json", logs)

    # rate limit 120/min
    logs_rl = _load("request_log.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl[-2000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                recent += 1
    if recent >= 120:
        _log("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    cu_wsp_re = re.compile(r"^cu_wsp_[0-9A-Z]{18,}$")
    cu_cnt_re = re.compile(r"^cu_cnt_[0-9A-Z]{18,}$")

    if not isinstance(workspaceId, str) or not cu_wsp_re.match(workspaceId):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]{18,}$")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO date-time string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            raise ValueError(f"{field} must be an ISO date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    try:
        due_after_dt = _parse_dt(due_after, "due_after")
        due_before_dt = _parse_dt(due_before, "due_before")
        updated_after_dt = _parse_dt(updated_after, "updated_after")
    except ValueError as e:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))

    if sort is not None and sort not in ("created_at", "updated_at", "due_date", "priority"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of created_at, updated_at, due_date, priority")
    if sort_dir is not None and sort_dir not in ("asc", "desc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_dir must be one of asc, desc")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    for arr, nm, pat in [
        (list_ids, "list_ids", cu_cnt_re),
        (folder_ids, "folder_ids", cu_cnt_re),
        (space_ids, "space_ids", cu_cnt_re),
    ]:
        if arr is not None:
            if not isinstance(arr, list):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{nm} must be an array")
            for v in arr:
                if not isinstance(v, str) or not pat.match(v):
                    _log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Each element of {nm} must match {pat.pattern}")

    if tags is not None and not (isinstance(tags, list) and all(isinstance(x, str) for x in tags)):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tags must be an array of strings when provided")
    if statuses is not None and not (isinstance(statuses, list) and all(isinstance(x, str) for x in statuses)):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "statuses must be an array of strings when provided")
    if assignee_clickup_user_ids is not None and not (isinstance(assignee_clickup_user_ids, list) and all(isinstance(x, str) for x in assignee_clickup_user_ids)):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "assignee_clickup_user_ids must be an array of strings when provided")
    if subtasks is not None and not isinstance(subtasks, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subtasks must be boolean when provided")
    if archived is not None and not isinstance(archived, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be boolean when provided")

    # At least one filter required
    if not any([
        tags, list_ids, folder_ids, space_ids, statuses, assignee_clickup_user_ids,
        subtasks is not None, archived is not None, due_after is not None, due_before is not None, updated_after is not None
    ]):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one filter parameter is required")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")
    activity = _load("task_activity.json")
    if not isinstance(workspaces, list) or not isinstance(containers, list) or not isinstance(tasks_rows, list) or not isinstance(activity, list):
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unavailable")

    wsp = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspaceId:
            wsp = w
            break
    if not wsp or wsp.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace not accessible")

    # Build container ancestry maps (only within workspace; include active+deleted since tasks may point at active lists)
    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspaceId and isinstance(c.get("id"), str)}
    parent_of = {}
    type_of = {}
    for cid, c in cont_by_id.items():
        parent_of[cid] = c.get("parent_id")
        type_of[cid] = c.get("type")

    def _ancestors(cid):
        seen = set()
        cur = cid
        out = []
        while cur and cur in cont_by_id and cur not in seen:
            seen.add(cur)
            p = parent_of.get(cur)
            if p:
                out.append(p)
            cur = p
        return out

    folder_set = set(folder_ids or [])
    space_set = set(space_ids or [])
    list_set = set(list_ids or [])

    # Precompute list ids under specified folders/spaces
    allowed_list_ids = None  # None = no restriction, else set
    if list_set:
        allowed_list_ids = set(list_set)

    if folder_set or space_set:
        derived = set()
        for cid, c in cont_by_id.items():
            if c.get("type") != "list":
                continue
            ancs = _ancestors(cid)
            if folder_set and any(a in folder_set for a in ancs) or (space_set and any(a in space_set for a in ancs)):
                derived.add(cid)
        allowed_list_ids = derived if allowed_list_ids is None else (allowed_list_ids & derived)

    # Tag filter: tasks that have any of these active task_tag rows
    tag_task_ids = None
    if tags:
        tag_set = set(tags)
        tag_task_ids = set()
        for a in activity:
            if not isinstance(a, dict):
                continue
            if a.get("workspace_id") != workspaceId or a.get("status") != "active" or a.get("kind") != "task_tag":
                continue
            if a.get("tag_name") in tag_set and isinstance(a.get("task_id"), str):
                tag_task_ids.add(a.get("task_id"))

    # Cursor decode
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(payload.decode("utf-8"))
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter tasks
    rows = []
    for t in tasks_rows:
        if not isinstance(t, dict):
            continue
        if t.get("workspace_id") != workspaceId:
            continue
        if t.get("status") != "active":
            continue

        # subtasks filter
        if subtasks is False and t.get("parent_task_id") is not None:
            continue
        if subtasks is True:
            pass  # include both
        else:
            pass  # default include both (ClickUp varies; keep inclusive)

        # archived filter not modeled: treat as always false (no field). If archived is False, keep; if True, none.
        if archived is True:
            continue

        if allowed_list_ids is not None:
            if t.get("list_container_id") not in allowed_list_ids:
                continue

        if statuses:
            if t.get("status_name") not in set(statuses):
                continue

        if assignee_clickup_user_ids:
            a_ids = t.get("assignee_clickup_user_ids")
            if not isinstance(a_ids, list):
                continue
            if not set(a_ids).intersection(set(assignee_clickup_user_ids)):
                continue

        # due window
        if due_after_dt or due_before_dt:
            dd = t.get("due_date")
            if dd is None:
                continue
            try:
                dd_dt = datetime.datetime.fromisoformat(dd.replace("Z", "+00:00")) if isinstance(dd, str) else None
            except Exception:
                continue
            if dd_dt is None:
                continue
            if dd_dt.tzinfo is None:
                dd_dt = dd_dt.replace(tzinfo=datetime.timezone.utc)
            if due_after_dt and not (dd_dt > due_after_dt):
                continue
            if due_before_dt and not (dd_dt < due_before_dt):
                continue

        if updated_after_dt:
            ua = t.get("updated_at")
            if ua is None or not isinstance(ua, str):
                continue
            try:
                ua_dt = datetime.datetime.fromisoformat(ua.replace("Z", "+00:00"))
            except Exception:
                continue
            if ua_dt.tzinfo is None:
                ua_dt = ua_dt.replace(tzinfo=datetime.timezone.utc)
            if not (ua_dt > updated_after_dt):
                continue

        if tag_task_ids is not None:
            if t.get("id") not in tag_task_ids:
                continue

        rows.append(t)

    # Sorting
    sfield = sort or "updated_at"
    sdir = sort_dir or "desc"

    def _key(t):
        v = t.get(sfield)
        if sfield in ("created_at", "updated_at", "due_date"):
            if not isinstance(v, str) or not v:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            try:
                dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            except Exception:
                dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        if sfield == "priority":
            if v is None:
                return -1
            return v if isinstance(v, int) else -1
        return v

    reverse = (sdir == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK", meta={"workspaceId": workspaceId, "returned": len(page), "total": total})
    return {
        "workspaceId": workspaceId,
        "tasks": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_task_time_entries(taskId=None, taskName=None, listName=None, start_time_after=None, start_time_before=None, end_time_after=None, end_time_before=None, running=None, billable=None, user_clickup_ids=None, tags=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get_task_time_entries",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            "meta": meta or {}
        })
        _save("request_log.json", logs)

    # rate limit 120/min
    logs_rl = _load("request_log.json")
    if not isinstance(logs_rl, list):
        logs_rl = []
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs_rl[-2000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                recent += 1
    if recent >= 120:
        _log("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    cu_tsk_re = re.compile(r"^cu_tsk_[0-9A-Z]{18,}$")

    # Validate task identifiers
    if taskId is not None:
        if not isinstance(taskId, str) or not cu_tsk_re.match(taskId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "taskId must match ^cu_tsk_[0-9A-Z]{18,}$")
    if taskId is None:
        if taskName is None or not isinstance(taskName, str) or taskName.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "taskId or taskName is required")
    if taskName is not None and (not isinstance(taskName, str) or taskName.strip() == ""):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string when provided")
    if listName is not None and (not isinstance(listName, str) or listName.strip() == ""):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO date-time string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            raise ValueError(f"{field} must be an ISO date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    try:
        sta = _parse_dt(start_time_after, "start_time_after")
        stb = _parse_dt(start_time_before, "start_time_before")
        eta = _parse_dt(end_time_after, "end_time_after")
        etb = _parse_dt(end_time_before, "end_time_before")
    except ValueError as e:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))

    if sta and stb and not (stb > sta):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time_before must be after start_time_after")
    if eta and etb and not (etb > eta):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time_before must be after end_time_after")

    if running is not None and not isinstance(running, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "running must be boolean when provided")
    if billable is not None and not isinstance(billable, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "billable must be boolean when provided")
    if user_clickup_ids is not None and not (isinstance(user_clickup_ids, list) and all(isinstance(x, str) for x in user_clickup_ids)):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_clickup_ids must be an array of strings when provided")
    if tags is not None and not (isinstance(tags, list) and all(isinstance(x, str) for x in tags)):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tags must be an array of strings when provided")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    # Load store
    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")
    activity = _load("task_activity.json")
    members = _load("members.json")
    if not isinstance(workspaces, list) or not isinstance(containers, list) or not isinstance(tasks_rows, list) or not isinstance(activity, list) or not isinstance(members, list):
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unavailable")

    # Resolve task:
    # - If taskId is provided: match tasks.clickup_task_id OR tasks.custom_task_id with ambiguity check
    #   (Note: tool param is named taskId but described as internal; business rules say taskId matches clickup/custom ids.
    #    We'll implement business rule; also accept internal id exact match if it exists uniquely.)
    # - If taskName: resolve within a workspace; if listName given, scope to that list.
    active_wsps = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
    if not active_wsps:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace available")

    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and isinstance(c.get("id"), str)}
    def _resolve_list_by_name_in_workspace(wsp_id, ln):
        ms = [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == wsp_id and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == ln]
        if len(ms) == 1:
            return ms[0]
        if len(ms) == 0:
            return None
        return "AMBIGUOUS_LIST"

    resolved_task = None
    resolved_workspace_id = None

    if taskId is not None:
        # search across active workspaces for matches by internal id, clickup_task_id, custom_task_id
        internal_matches = []
        clickup_matches = []
        custom_matches = []
        for t in tasks_rows:
            if not isinstance(t, dict) or t.get("status") != "active":
                continue
            wsp_id = t.get("workspace_id")
            if wsp_id not in {w.get("id") for w in active_wsps}:
                continue
            if t.get("id") == taskId:
                internal_matches.append(t)
            if t.get("clickup_task_id") == taskId:
                clickup_matches.append(t)
            if t.get("custom_task_id") == taskId:
                custom_matches.append(t)

        # Apply business rule for clickup_task_id vs custom_task_id ambiguity
        # If both match different tasks -> ambiguity error (use CONFLICT code with extra hint)
        cand = None
        if clickup_matches and custom_matches:
            # if any pair differs
            if any(cm.get("id") != um.get("id") for cm in clickup_matches for um in custom_matches):
                _log("CONFLICT")
                return _err("CONFLICT", "Ambiguous taskId: matches both clickup_task_id and custom_task_id for different tasks", taskId=taskId)
            cand = clickup_matches[0]
        elif clickup_matches:
            cand = clickup_matches[0] if len(clickup_matches) == 1 else None
            if cand is None:
                _log("CONFLICT")
                return _err("CONFLICT", "Ambiguous taskId: multiple tasks share the same clickup_task_id", taskId=taskId)
        elif custom_matches:
            cand = custom_matches[0] if len(custom_matches) == 1 else None
            if cand is None:
                _log("CONFLICT")
                return _err("CONFLICT", "Ambiguous taskId: multiple tasks share the same custom_task_id", taskId=taskId)
        elif internal_matches:
            cand = internal_matches[0] if len(internal_matches) == 1 else None
            if cand is None:
                _log("CONFLICT")
                return _err("CONFLICT", "Ambiguous internal task id across workspaces", taskId=taskId)

        if cand is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Task not found", taskId=taskId)

        resolved_task = cand
        resolved_workspace_id = cand.get("workspace_id")
    else:
        # resolve by name, optionally by listName
        tn = taskName.strip()
        candidates = []
        for w in active_wsps:
            wsp_id = w.get("id")
            if not isinstance(wsp_id, str):
                continue
            if listName is not None:
                lst = _resolve_list_by_name_in_workspace(wsp_id, listName.strip())
                if lst is None:
                    continue
                if lst == "AMBIGUOUS_LIST":
                    _log("CONFLICT")
                    return _err("CONFLICT", "listName is ambiguous within a workspace; use taskId", listName=listName)
                for t in tasks_rows:
                    if isinstance(t, dict) and t.get("workspace_id") == wsp_id and t.get("status") == "active" and t.get("list_container_id") == lst.get("id") and t.get("name") == tn:
                        candidates.append(t)
            else:
                for t in tasks_rows:
                    if isinstance(t, dict) and t.get("workspace_id") == wsp_id and t.get("status") == "active" and t.get("name") == tn:
                        candidates.append(t)
        if len(candidates) == 0:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Task not found by name", taskName=taskName, listName=listName)
        if len(candidates) > 1 and listName is None:
            _log("CONFLICT")
            return _err("CONFLICT", "Task name is ambiguous within the workspace; provide listName or use taskId", taskName=taskName)
        if len(candidates) > 1 and listName is not None:
            _log("CONFLICT")
            return _err("CONFLICT", "Task name is ambiguous within the list; use taskId", taskName=taskName, listName=listName)

        resolved_task = candidates[0]
        resolved_workspace_id = resolved_task.get("workspace_id")

    # Cursor decode (offset paging)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(payload.decode("utf-8"))
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Build member lookup for user info (by member id)
    mem_by_id = {m.get("id"): m for m in members if isinstance(m, dict) and m.get("workspace_id") == resolved_workspace_id}

    # Filter time entries
    tid_internal = resolved_task.get("id")
    rows = []
    tag_set = set(tags) if tags else None
    user_set = set(user_clickup_ids) if user_clickup_ids else None

    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("workspace_id") != resolved_workspace_id:
            continue
        if a.get("status") != "active":
            continue
        if a.get("kind") != "time_entry":
            continue
        if a.get("task_id") != tid_internal:
            continue

        if running is not None:
            if bool(a.get("running")) != running:
                continue
        if billable is not None:
            if bool(a.get("billable")) != billable:
                continue

        # time window filters
        st = a.get("start_time")
        et = a.get("end_time")
        try:
            st_dt = datetime.datetime.fromisoformat(st.replace("Z", "+00:00")) if isinstance(st, str) else None
        except Exception:
            st_dt = None
        try:
            et_dt = datetime.datetime.fromisoformat(et.replace("Z", "+00:00")) if isinstance(et, str) else None
        except Exception:
            et_dt = None
        if st_dt and st_dt.tzinfo is None:
            st_dt = st_dt.replace(tzinfo=datetime.timezone.utc)
        if et_dt and et_dt.tzinfo is None:
            et_dt = et_dt.replace(tzinfo=datetime.timezone.utc)

        if sta and (st_dt is None or not (st_dt > sta)):
            continue
        if stb and (st_dt is None or not (st_dt < stb)):
            continue
        if eta:
            # if entry running (end_time null), it can't match end_time_after
            if et_dt is None or not (et_dt > eta):
                continue
        if etb:
            if et_dt is None or not (et_dt < etb):
                continue

        if user_set is not None:
            am = mem_by_id.get(a.get("author_member_id"))
            cu_uid = am.get("clickup_user_id") if isinstance(am, dict) else None
            if cu_uid not in user_set:
                continue

        if tag_set is not None:
            te_tags = a.get("time_entry_tags")
            if not isinstance(te_tags, list) or not set(te_tags).intersection(tag_set):
                continue

        rows.append(a)

    # Sort by start_time desc, then id desc (stable paging)
    def _dt_or_min(v):
        if not isinstance(v, str) or not v:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    rows.sort(key=lambda r: (_dt_or_min(r.get("start_time")), str(r.get("id") or "")), reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]

    # Enrich with user info
    enriched = []
    for r in page:
        am = mem_by_id.get(r.get("author_member_id"))
        enriched.append({
            **r,
            "user": None if not isinstance(am, dict) else {
                "member_id": am.get("id"),
                "clickup_user_id": am.get("clickup_user_id"),
                "full_name": am.get("full_name"),
                "username": am.get("username"),
                "email": am.get("email"),
                "role": am.get("role")
            }
        })

    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK", meta={"task_id": tid_internal, "returned": len(enriched), "total": total})
    return {
        "task": {"id": resolved_task.get("id"), "name": resolved_task.get("name"), "workspace_id": resolved_workspace_id},
        "time_entries": enriched,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def start_time_tracking(workspaceId, taskId=None, taskName=None, listName=None, description=None, billable=None, tags=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage / request log (best-effort, but must persist if collection exists)
    req_log_file = "request_log.json"
    usage_file = "usage.json"
    req_log = _load(req_log_file)
    usage = _load(usage_file)

    def _log(status, credential_id=None, extra=None):
        nonlocal req_log, usage
        dt = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(req_log)+1}",
            "endpoint": "start_time_tracking",
            "timestamp": now,
            "status": status,
            "latency_ms": dt,
            "credential_id": credential_id,
        }
        if extra:
            row.update(extra)
        req_log.append(row)
        _save(req_log_file, req_log)

        # simple counters/quota if present
        if isinstance(usage, list) and usage:
            u = usage[0] if isinstance(usage[0], dict) else None
            if isinstance(u, dict):
                u["requests_total"] = int(u.get("requests_total", 0)) + 1
                u["requests_today"] = int(u.get("requests_today", 0)) + 1
                u["updated_at"] = now
                _save(usage_file, usage)

    # Validate inputs
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId or ""):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workspaceId is missing or invalid.")

    if taskId is None and taskName is None:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required.")

    if taskId is not None:
        if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]{18,}$", taskId or ""):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "taskId is invalid.")
    if taskName is not None:
        if not isinstance(taskName, str) or len(taskName.strip()) < 1:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "taskName must be a non-empty string.")
    if listName is not None:
        if not isinstance(listName, str) or len(listName.strip()) < 1:
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "listName must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description must be a string.")
    if billable is not None and not isinstance(billable, bool):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "billable must be a boolean.")
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(x, str)) for x in tags):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.")

    workspaces = _load("workspaces.json")
    members = _load("members.json")
    containers = _load("containers.json")
    tasks = _load("tasks.json")
    activity = _load("task_activity.json")

    # Resolve workspace (by clickup_team_id per tool surface)
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("clickup_team_id") == workspaceId and w.get("status") == "active"), None)
    if not wsp:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    workspace_internal_id = wsp.get("id")

    # Resolve calling member (ambient auth): pick an active member in this workspace, prefer owner/admin
    workspace_members = [m for m in members if isinstance(m, dict) and m.get("workspace_id") == workspace_internal_id and m.get("status") == "active"]
    if not workspace_members:
        _log("error", extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active member context available for this workspace.")
    role_rank = {"owner": 3, "admin": 2, "member": 1, "guest": 0}
    workspace_members.sort(key=lambda m: role_rank.get(m.get("role"), 0), reverse=True)
    caller_member = workspace_members[0]

    # Task resolution
    def _find_list_by_name(nm):
        nm2 = nm.strip()
        return [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspace_internal_id and c.get("type") == "list" and c.get("status") == "active" and (c.get("name") or "") == nm2]

    resolved_task = None
    if taskId is not None:
        by_clickup = [t for t in tasks if isinstance(t, dict) and t.get("workspace_id") == workspace_internal_id and t.get("status") == "active" and t.get("clickup_task_id") == taskId]
        by_custom = [t for t in tasks if isinstance(t, dict) and t.get("workspace_id") == workspace_internal_id and t.get("status") == "active" and t.get("custom_task_id") == taskId]
        if by_clickup and by_custom and by_clickup[0].get("id") != by_custom[0].get("id"):
            _log("error", extra={"error_code": "CONFLICT"})
            return _err("CONFLICT", "taskId is ambiguous (matches both clickup_task_id and custom_task_id for different tasks).")
        resolved_task = (by_clickup or by_custom or [None])[0]
        if not resolved_task:
            _log("error", extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Task not found.")
    else:
        # Resolve by name; listName can scope
        tname = taskName.strip()
        candidates = [t for t in tasks if isinstance(t, dict) and t.get("workspace_id") == workspace_internal_id and t.get("status") == "active" and (t.get("name") or "") == tname]
        if listName is not None:
            lists = _find_list_by_name(listName)
            if not lists:
                _log("error", extra={"error_code": "NOT_FOUND"})
                return _err("NOT_FOUND", "List not found for provided listName.")
            list_ids = {c.get("id") for c in lists}
            candidates = [t for t in candidates if t.get("list_container_id") in list_ids]
        else:
            # business rule: taskName without listName must be unique among active matches
            if len(candidates) > 1:
                _log("error", extra={"error_code": "CONFLICT"})
                return _err("CONFLICT", "taskName is ambiguous (multiple active tasks match); provide listName to disambiguate.")
        resolved_task = candidates[0] if len(candidates) == 1 else None
        if not resolved_task:
            _log("error", extra={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Task not found.")

    task_internal_id = resolved_task.get("id")

    # Enforce unique active running time entry per (workspace_id, author_member_id)
    running = next((a for a in activity
                    if isinstance(a, dict)
                    and a.get("workspace_id") == workspace_internal_id
                    and a.get("kind") == "time_entry"
                    and a.get("status") == "active"
                    and a.get("author_member_id") == caller_member.get("id")
                    and a.get("running") is True), None)
    if running:
        _log("error", extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "A running time entry already exists for this member in this workspace.", timeEntry=running)

    # Create activity row
    def _new_id(prefix):
        base = f"{prefix}{int(time.time()*1000)}"
        return base + "_" + str(len(activity) + 1)

    new_row = {
        "id": _new_id("act_"),
        "workspace_id": workspace_internal_id,
        "task_id": task_internal_id,
        "space_container_id": None,
        "kind": "time_entry",
        "clickup_id": f"cu_act_{int(time.time()*1000):018d}",
        "author_member_id": caller_member.get("id"),
        "assignee_member_id": None,
        "notify_all": None,
        "body_text": None,
        "attachment_filename": None,
        "attachment_source_type": None,
        "attachment_url": None,
        "attachment_size_bytes": None,
        "tag_name": None,
        "tag_color": None,
        "billable": billable if billable is not None else None,
        "time_entry_description": description if description is not None else None,
        "time_entry_tags": tags if tags is not None else None,
        "start_time": now,
        "end_time": None,
        "duration_ms": None,
        "running": True,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Constraint checks
    if new_row["task_id"] is None or new_row["author_member_id"] is None or new_row["start_time"] is None:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid time entry payload (missing required fields).")

    activity.append(new_row)
    _save("task_activity.json", activity)

    _log("ok", extra={"workspace_internal_id": workspace_internal_id, "task_id": task_internal_id})
    return {"time_entry": new_row}

def stop_time_tracking(workspaceId, description=None, tags=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    req_log_file = "request_log.json"
    usage_file = "usage.json"
    req_log = _load(req_log_file)
    usage = _load(usage_file)

    def _log(status, extra=None):
        nonlocal req_log, usage
        dt = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(req_log)+1}",
            "endpoint": "stop_time_tracking",
            "timestamp": now,
            "status": status,
            "latency_ms": dt,
            "credential_id": None,
        }
        if extra:
            row.update(extra)
        req_log.append(row)
        _save(req_log_file, req_log)

        if isinstance(usage, list) and usage:
            u = usage[0] if isinstance(usage[0], dict) else None
            if isinstance(u, dict):
                u["requests_total"] = int(u.get("requests_total", 0)) + 1
                u["requests_today"] = int(u.get("requests_today", 0)) + 1
                u["updated_at"] = now
                _save(usage_file, usage)

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId or ""):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workspaceId is missing or invalid.")
    if description is not None and not isinstance(description, str):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description must be a string.")
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(x, str)) for x in tags):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings.")

    workspaces = _load("workspaces.json")
    members = _load("members.json")
    activity = _load("task_activity.json")

    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("clickup_team_id") == workspaceId and w.get("status") == "active"), None)
    if not wsp:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    workspace_internal_id = wsp.get("id")

    workspace_members = [m for m in members if isinstance(m, dict) and m.get("workspace_id") == workspace_internal_id and m.get("status") == "active"]
    if not workspace_members:
        _log("error", extra={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active member context available for this workspace.")
    role_rank = {"owner": 3, "admin": 2, "member": 1, "guest": 0}
    workspace_members.sort(key=lambda m: role_rank.get(m.get("role"), 0), reverse=True)
    caller_member = workspace_members[0]

    running_idx = None
    for i, a in enumerate(activity):
        if not isinstance(a, dict):
            continue
        if (a.get("workspace_id") == workspace_internal_id and a.get("kind") == "time_entry"
                and a.get("status") == "active" and a.get("author_member_id") == caller_member.get("id")
                and a.get("running") is True):
            running_idx = i
            break

    if running_idx is None:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No running time entry to stop in this workspace.")

    row = activity[running_idx]
    # Conflict if row is malformed vs running invariants
    if row.get("end_time") is not None or row.get("duration_ms") is not None:
        _log("error", extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Running time entry is in an inconsistent state.")

    # Parse start_time
    st = row.get("start_time")
    try:
        if isinstance(st, str) and st.endswith("Z"):
            st_dt = datetime.datetime.fromisoformat(st[:-1])
        else:
            st_dt = datetime.datetime.fromisoformat(st)
    except Exception:
        _log("error", extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Running time entry has invalid start_time.")

    if now_dt < st_dt:
        _log("error", extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Clock skew: end_time is before start_time.")

    duration_ms = int((now_dt - st_dt).total_seconds() * 1000)
    if duration_ms < 0:
        duration_ms = 0

    row["end_time"] = now
    row["duration_ms"] = duration_ms
    row["running"] = False
    if description is not None:
        row["time_entry_description"] = description
    if tags is not None:
        row["time_entry_tags"] = tags
    row["updated_at"] = now
    activity[running_idx] = row
    _save("task_activity.json", activity)

    _log("ok", extra={"workspace_internal_id": workspace_internal_id, "time_entry_id": row.get("clickup_id")})
    return {"time_entry": row}

def add_time_entry(workspaceId, startTime, durationMs, taskId=None, taskName=None, listName=None, description=None, billable=None, tags=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_time_entry"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        try:
            ss = s.strip()
            ss2 = ss[:-1] if ss.endswith("Z") else ss
            dt = datetime.datetime.fromisoformat(ss2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}{''.join(secrets.choice(alphabet) for _ in range(22))}"

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        e = _err("VALIDATION_ERROR", "workspaceId is missing or invalid.")
        _log("error", "VALIDATION_ERROR")
        return e
    wsid = workspaceId.strip()

    st_dt, err = _parse_dt(startTime, "startTime")
    if err:
        _log("error", err["error"]["code"])
        return err

    if not isinstance(durationMs, int) or durationMs < 1:
        e = _err("VALIDATION_ERROR", "durationMs must be an integer >= 1.")
        _log("error", "VALIDATION_ERROR")
        return e

    if taskId is None and taskName is None:
        e = _err("VALIDATION_ERROR", "Provide taskId or taskName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskId is not None and (not isinstance(taskId, str) or not taskId.strip()):
        e = _err("VALIDATION_ERROR", "taskId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        e = _err("VALIDATION_ERROR", "taskName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        e = _err("VALIDATION_ERROR", "listName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if billable is not None and not isinstance(billable, bool):
        e = _err("VALIDATION_ERROR", "billable must be a boolean when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if tags is not None:
        if not isinstance(tags, list):
            e = _err("VALIDATION_ERROR", "tags must be an array when provided.")
            _log("error", "VALIDATION_ERROR")
            return e
        for t in tags:
            if not isinstance(t, str):
                e = _err("VALIDATION_ERROR", "tags must be an array of strings.")
                _log("error", "VALIDATION_ERROR")
                return e

    workspaces = _load("workspaces.json")
    tasks = _load("tasks.json")
    containers = _load("containers.json")
    members = _load("members.json")
    activity = _load("task_activity.json")
    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(containers, list):
        containers = []
    if not isinstance(members, list):
        members = []
    if not isinstance(activity, list):
        activity = []

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == wsid:
            ws = w
            break
    if not ws or ws.get("status") != "active":
        e = _err("UNAUTHORIZED", "Workspace is not available.", workspaceId=wsid, workspaceStatus=(ws.get("status") if ws else None))
        _log("error", "UNAUTHORIZED")
        return e

    def _resolve_task():
        if taskId is not None:
            tid = taskId.strip()
            clickup_matches = []
            custom_matches = []
            internal_matches = []
            for t in tasks:
                if not isinstance(t, dict):
                    continue
                if t.get("workspace_id") != wsid or t.get("status") != "active":
                    continue
                if t.get("clickup_task_id") == tid:
                    clickup_matches.append(t)
                if t.get("custom_task_id") and t.get("custom_task_id") == tid:
                    custom_matches.append(t)
                if t.get("id") == tid:
                    internal_matches.append(t)
            ids = {x.get("id") for x in (clickup_matches + custom_matches + internal_matches) if x.get("id")}
            if len(ids) == 0:
                return None, _err("NOT_FOUND", "task not found", taskId=tid)
            if len(ids) > 1:
                return None, _err("CONFLICT", "taskId is ambiguous (matched multiple tasks).", taskId=tid, matches=len(ids))
            return (clickup_matches + custom_matches + internal_matches)[0], None

        tn = taskName.strip()
        if listName is not None:
            ln = listName.strip()
            list_candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active" and c.get("workspace_id") == wsid and c.get("name") == ln]
            if len(list_candidates) == 0:
                return None, _err("NOT_FOUND", "list not found for listName scope", listName=ln, workspaceId=wsid)
            if len(list_candidates) > 1:
                return None, _err("CONFLICT", "listName is ambiguous; cannot resolve taskName.", listName=ln, matches=len(list_candidates))
            list_id = list_candidates[0].get("id")
            hits = [t for t in tasks if isinstance(t, dict) and t.get("workspace_id") == wsid and t.get("status") == "active" and t.get("list_container_id") == list_id and t.get("name") == tn]
            if len(hits) == 0:
                return None, _err("NOT_FOUND", "task not found", taskName=tn, listName=ln)
            if len(hits) > 1:
                return None, _err("CONFLICT", "taskName is ambiguous within listName scope.", taskName=tn, listName=ln, matches=len(hits))
            return hits[0], None
        else:
            hits = [t for t in tasks if isinstance(t, dict) and t.get("workspace_id") == wsid and t.get("status") == "active" and t.get("name") == tn]
            if len(hits) == 0:
                return None, _err("NOT_FOUND", "task not found", taskName=tn)
            if len(hits) > 1:
                return None, _err("CONFLICT", "taskName is ambiguous within workspace (provide listName).", taskName=tn, matches=len(hits))
            return hits[0], None

    task, err = _resolve_task()
    if err:
        _log("error", err["error"]["code"])
        return err

    # author_member_id: choose an active member in workspace (ambient auth not modeled)
    author_member_id = None
    for m in members:
        if isinstance(m, dict) and m.get("workspace_id") == wsid and m.get("status") == "active":
            author_member_id = m.get("id")
            break
    if not author_member_id:
        e = _err("UNAUTHORIZED", "No active member available in workspace to attribute time entry.", workspaceId=wsid)
        _log("error", "UNAUTHORIZED")
        return e

    end_dt = st_dt + datetime.timedelta(milliseconds=durationMs)
    now = _now()

    new_row = {
        "id": _gen_id("cu_act_"),
        "workspace_id": wsid,
        "task_id": task.get("id"),
        "space_container_id": None,
        "kind": "time_entry",
        "clickup_id": _gen_id("cu_act_"),  # upstream-like time entry id
        "author_member_id": author_member_id,
        "assignee_member_id": None,
        "notify_all": None,
        "body_text": None,
        "attachment_filename": None,
        "attachment_source_type": None,
        "attachment_url": None,
        "attachment_size_bytes": None,
        "tag_name": None,
        "tag_color": None,
        "billable": (billable if billable is not None else None),
        "time_entry_description": (description if description is not None else None),
        "time_entry_tags": (tags if tags is not None else None),
        "start_time": st_dt.isoformat().replace("+00:00", "Z"),
        "end_time": end_dt.isoformat().replace("+00:00", "Z"),
        "duration_ms": durationMs,
        "running": False,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    activity.append(new_row)
    _save("task_activity.json", activity)

    _log("ok", meta={"time_entry_id": new_row["clickup_id"], "activity_row_id": new_row["id"], "task_id": task.get("id")})
    return {"time_entry": new_row}

def delete_time_entry(timeEntryId, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_time_entry"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    if not isinstance(timeEntryId, str) or not re.match(r"^cu_act_[0-9A-Z]{18,}$", timeEntryId or ""):
        e = _err("VALIDATION_ERROR", "timeEntryId is missing or invalid.")
        _log("error", "VALIDATION_ERROR")
        return e

    activity = _load("task_activity.json")
    if not isinstance(activity, list):
        activity = []

    idx = None
    for i, a in enumerate(activity):
        if not isinstance(a, dict):
            continue
        if a.get("kind") == "time_entry" and a.get("clickup_id") == timeEntryId:
            idx = i
            break

    if idx is None:
        e = _err("NOT_FOUND", "Time entry not found.", timeEntryId=timeEntryId)
        _log("error", "NOT_FOUND")
        return e

    row = activity[idx]
    now = _now()
    if row.get("status") == "deleted":
        # idempotent delete
        _log("ok", meta={"timeEntryId": timeEntryId, "already_deleted": True})
        return {"timeEntryId": timeEntryId, "status": "deleted", "already_deleted": True}

    if row.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Time entry is not active and cannot be deleted.", timeEntryId=timeEntryId, status=row.get("status"))
        _log("error", "INVALID_TRANSITION")
        return e

    row["status"] = "deleted"
    if row.get("running") is True:
        row["running"] = False
        row["end_time"] = now
        # duration unknown; leave as-is if missing
    row["updated_at"] = now

    _save("task_activity.json", activity)
    _log("ok", meta={"timeEntryId": timeEntryId, "activity_row_id": row.get("id")})
    return {"timeEntryId": timeEntryId, "status": "deleted"}

def create_list(workspaceId, spaceId=None, spaceName=None, name=None, content=None, dueDate=None, priority=None, assigneeId=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        try:
            ss = s.strip()
            ss2 = ss[:-1] if ss.endswith("Z") else ss
            dt = datetime.datetime.fromisoformat(ss2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt.isoformat().replace("+00:00", "Z"), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}{''.join(secrets.choice(alphabet) for _ in range(22))}"

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        e = _err("VALIDATION_ERROR", "workspaceId must be a non-empty string")
        _log("error", "VALIDATION_ERROR")
        return e
    wsid = workspaceId.strip()

    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", rule="name <> ''")
        _log("error", "VALIDATION_ERROR")
        return e
    list_name = name.strip()

    if content is not None and not isinstance(content, str):
        e = _err("VALIDATION_ERROR", "content must be a string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    due_iso, err = _parse_dt(dueDate, "dueDate")
    if err:
        _log("error", err["error"]["code"])
        return err

    if priority is not None:
        if not isinstance(priority, int):
            e = _err("VALIDATION_ERROR", "priority must be an integer when provided.")
            _log("error", "VALIDATION_ERROR")
            return e
        if priority < 0 or priority > 4:
            e = _err("VALIDATION_ERROR", "priority must be between 0 and 4.", rule="priority is null or (priority >= 0 and priority <= 4)")
            _log("error", "VALIDATION_ERROR")
            return e

    if assigneeId is not None and (not isinstance(assigneeId, str) or not assigneeId.strip()):
        e = _err("VALIDATION_ERROR", "assigneeId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    if status is not None and (not isinstance(status, str) or status not in ("active", "deleted")):
        e = _err("VALIDATION_ERROR", "status must be 'active' or 'deleted' when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    if spaceId is None and spaceName is None:
        e = _err("VALIDATION_ERROR", "You must provide spaceId or spaceName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if spaceId is not None and (not isinstance(spaceId, str) or not spaceId.strip()):
        e = _err("VALIDATION_ERROR", "spaceId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e
    if spaceName is not None and (not isinstance(spaceName, str) or not spaceName.strip()):
        e = _err("VALIDATION_ERROR", "spaceName must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    members = _load("members.json")
    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(containers, list):
        containers = []
    if not isinstance(members, list):
        members = []

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == wsid:
            ws = w
            break
    if not ws or ws.get("status") != "active":
        e = _err("UNAUTHORIZED", "Workspace is not available.", workspaceId=wsid, workspaceStatus=(ws.get("status") if ws else None))
        _log("error", "UNAUTHORIZED")
        return e

    # Resolve parent space
    space = None
    if spaceId is not None:
        sid = spaceId.strip()
        for c in containers:
            if isinstance(c, dict) and c.get("id") == sid and c.get("type") == "space" and c.get("status") == "active" and c.get("workspace_id") == wsid:
                space = c
                break
        if not space:
            e = _err("NOT_FOUND", "space not found", spaceId=sid, workspaceId=wsid)
            _log("error", "NOT_FOUND")
            return e
    else:
        sn = spaceName.strip()
        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "space" and c.get("status") == "active" and c.get("workspace_id") == wsid and c.get("name") == sn]
        if len(candidates) == 0:
            e = _err("NOT_FOUND", "space not found", spaceName=sn, workspaceId=wsid)
            _log("error", "NOT_FOUND")
            return e
        if len(candidates) > 1:
            e = _err("CONFLICT", "spaceName is ambiguous within workspace; provide spaceId.", spaceName=sn, matches=len(candidates))
            _log("error", "CONFLICT")
            return e
        space = candidates[0]

    # Resolve assignee member id (optional) must reference members.id if set
    assignee_member_id = None
    if assigneeId is not None:
        tok = assigneeId.strip()
        for m in members:
            if isinstance(m, dict) and m.get("id") == tok and m.get("workspace_id") == wsid and m.get("status") == "active":
                assignee_member_id = tok
                break
        if assignee_member_id is None:
            e = _err("NOT_FOUND", "assigneeId member not found in workspace.", assigneeId=tok, workspaceId=wsid)
            _log("error", "NOT_FOUND")
            return e

    now = _now()
    new_row = {
        "id": _gen_id("cu_cnt_"),
        "workspace_id": wsid,
        "type": "list",
        "parent_id": space.get("id"),
        "clickup_id": _gen_id("culst_"),
        "name": list_name,
        "content": (content if content is not None else None),
        "archived": False,
        "due_date": due_iso,
        "priority": priority,
        "assignee_member_id": assignee_member_id,
        "override_statuses": None,
        "status": (status if status is not None else "active"),
        "created_at": now,
        "updated_at": now,
    }

    containers.append(new_row)
    _save("containers.json", containers)

    _log("ok", meta={"list_id": new_row["id"], "workspace_id": wsid, "space_id": space.get("id")})
    return {"list": new_row}

def get_list(workspaceId, listId=None, listName=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    now = _now()

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId):
        return _err("VALIDATION_ERROR", "workspaceId must be a string matching ^cu_wsp_[0-9A-Z]{18,}$")
    if listId is None and listName is None:
        return _err("VALIDATION_ERROR", "Either listId or listName is required")
    if listId is not None and (not isinstance(listId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", listId)):
        return _err("VALIDATION_ERROR", "listId must match ^cu_cnt_[0-9A-Z]{18,}$")
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        return _err("VALIDATION_ERROR", "listName must be a non-empty string")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")

    wsp = next((w for w in workspaces if w.get("clickup_team_id") == workspaceId and w.get("status") != "deleted"), None)
    if not wsp:
        logs = _load("request_log.json")
        logs.append({"id": f"cu_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}", "tool": "get_list", "workspace_clickup_team_id": workspaceId, "workspace_id": None, "status": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time()-t0)*1000)})
        _save("request_log.json", logs)
        return _err("NOT_FOUND", "Workspace not found")
    if wsp.get("status") != "active":
        logs = _load("request_log.json")
        logs.append({"id": f"cu_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}", "tool": "get_list", "workspace_id": wsp.get("id"), "status": "UNAUTHORIZED", "timestamp": now, "latency_ms": int((time.time()-t0)*1000)})
        _save("request_log.json", logs)
        return _err("UNAUTHORIZED", "Workspace is not active")

    lst = None
    if listId is not None:
        lst = next((c for c in containers if c.get("id") == listId and c.get("workspace_id") == wsp.get("id") and c.get("type") == "list"), None)
        if not lst or lst.get("status") != "active":
            logs = _load("request_log.json")
            logs.append({"id": f"cu_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}", "tool": "get_list", "workspace_id": wsp.get("id"), "status": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time()-t0)*1000)})
            _save("request_log.json", logs)
            return _err("NOT_FOUND", "List not found in workspace")
    else:
        matches = [
            c for c in containers
            if c.get("workspace_id") == wsp.get("id")
            and c.get("type") == "list"
            and c.get("status") == "active"
            and (c.get("name") or "").lower() == listName.strip().lower()
        ]
        if len(matches) == 0:
            logs = _load("request_log.json")
            logs.append({"id": f"cu_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}", "tool": "get_list", "workspace_id": wsp.get("id"), "status": "NOT_FOUND", "timestamp": now, "latency_ms": int((time.time()-t0)*1000)})
            _save("request_log.json", logs)
            return _err("NOT_FOUND", "listName did not resolve to an active list", field="listName")
        if len(matches) > 1:
            logs = _load("request_log.json")
            logs.append({"id": f"cu_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}", "tool": "get_list", "workspace_id": wsp.get("id"), "status": "CONFLICT", "timestamp": now, "latency_ms": int((time.time()-t0)*1000)})
            _save("request_log.json", logs)
            return _err("CONFLICT", "listName is ambiguous in workspace", field="listName", matches=[m.get("id") for m in matches])
        lst = matches[0]

    # compute ancestry: folder (optional) and space (required)
    folder = None
    space = None
    parent_id = lst.get("parent_id")
    parent = next((c for c in containers if c.get("id") == parent_id and c.get("workspace_id") == wsp.get("id")), None) if parent_id else None
    if parent:
        if parent.get("type") == "folder":
            folder = parent
            space = next((c for c in containers if c.get("id") == folder.get("parent_id") and c.get("type") == "space" and c.get("workspace_id") == wsp.get("id")), None)
        elif parent.get("type") == "space":
            space = parent

    logs = _load("request_log.json")
    logs.append({
        "id": f"cu_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
        "tool": "get_list",
        "workspace_id": wsp.get("id"),
        "status": "OK",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000),
    })
    _save("request_log.json", logs)

    return {
        "list": lst,
        "ancestry": {
            "space": {"id": space.get("id"), "name": space.get("name")} if space else None,
            "folder": {"id": folder.get("id"), "name": folder.get("name")} if folder else None
        }
    }

def update_list(listId=None, listName=None, folderId=None, spaceId=None, folderName=None, spaceName=None, name=None, content=None, status=None, archived=None, due_date=None, priority=None, assigneeMemberId=None, override_statuses=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_list"

    # --- helpers ---
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "INVALID_TYPE"
        try:
            x = s
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(microsecond=0).isoformat() + "Z"
        except Exception:
            return "INVALID_FORMAT"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_log.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_workspace_context_for_container(container_row):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == container_row.get("workspace_id") and w.get("status") == "active"), None)
        return ws

    def _container_by_id(containers, cid):
        return next((c for c in containers if c.get("id") == cid), None)

    def _resolve_space(containers, spaceId, spaceName):
        # Return (space_row or None, error_obj or None, ambiguous_bool)
        if spaceId is not None:
            if not isinstance(spaceId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", spaceId):
                return None, _err("VALIDATION_ERROR", "spaceId is invalid."), False
            c = _container_by_id(containers, spaceId)
            if not c or c.get("type") != "space":
                return None, _err("NOT_FOUND", "Space not found."), False
            if c.get("status") != "active":
                return None, _err("NOT_FOUND", "Space not found."), False
            return c, None, False

        if spaceName is not None:
            if not isinstance(spaceName, str) or not spaceName.strip():
                return None, _err("VALIDATION_ERROR", "spaceName is invalid."), False
            matches = [c for c in containers if c.get("type") == "space" and c.get("status") == "active" and c.get("name") == spaceName]
            if len(matches) == 0:
                return None, _err("NOT_FOUND", "Space not found."), False
            if len(matches) > 1:
                return None, _err("CONFLICT", "spaceName is ambiguous; provide spaceId.", matches=[m.get("id") for m in matches]), True
            return matches[0], None, False

        return None, None, False

    def _resolve_folder(containers, folderId, folderName, space_row):
        if folderId is not None:
            if not isinstance(folderId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", folderId):
                return None, _err("VALIDATION_ERROR", "folderId is invalid.")
            c = _container_by_id(containers, folderId)
            if not c or c.get("type") != "folder" or c.get("status") != "active":
                return None, _err("NOT_FOUND", "Folder not found.")
            if space_row is not None and c.get("parent_id") != space_row.get("id"):
                return None, _err("NOT_FOUND", "Folder not found in the specified space.")
            return c, None

        if folderName is not None:
            if not isinstance(folderName, str) or not folderName.strip():
                return None, _err("VALIDATION_ERROR", "folderName is invalid.")
            if space_row is None:
                return None, _err("VALIDATION_ERROR", "Resolving folderName requires a resolved spaceId/spaceName for disambiguation.")
            matches = [c for c in containers if c.get("type") == "folder" and c.get("status") == "active" and c.get("name") == folderName and c.get("parent_id") == space_row.get("id")]
            if len(matches) == 0:
                return None, _err("NOT_FOUND", "Folder not found.")
            if len(matches) > 1:
                return None, _err("CONFLICT", "folderName is ambiguous in the specified space; provide folderId.", matches=[m.get("id") for m in matches])
            return matches[0], None

        return None, None

    def _resolve_list(containers):
        # listId preferred
        if listId is not None:
            if not isinstance(listId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", listId):
                return None, _err("VALIDATION_ERROR", "listId is invalid.")
            c = _container_by_id(containers, listId)
            if not c or c.get("type") != "list":
                return None, _err("NOT_FOUND", "List not found.")
            return c, None

        if listName is None:
            return None, _err("VALIDATION_ERROR", "Either listId or listName must be provided.")

        if not isinstance(listName, str) or not listName.strip():
            return None, _err("VALIDATION_ERROR", "listName is invalid.")

        # scoped name resolution for listName: type='list' and status='active'
        space_row, e, _amb = _resolve_space(containers, spaceId, spaceName)
        if e:
            return None, e
        folder_row, e2 = _resolve_folder(containers, folderId, folderName, space_row)
        if e2:
            return None, e2

        candidates = [c for c in containers if c.get("type") == "list" and c.get("status") == "active" and c.get("name") == listName]
        # Apply folder/space scoping when available
        if folder_row is not None:
            candidates = [c for c in candidates if c.get("parent_id") == folder_row.get("id")]
        elif space_row is not None:
            # list can be directly under space OR under folder under space
            def _in_space(list_row):
                pid = list_row.get("parent_id")
                p = _container_by_id(containers, pid) if pid else None
                if not p:
                    return False
                if p.get("type") == "space":
                    return p.get("id") == space_row.get("id")
                if p.get("type") == "folder":
                    return p.get("parent_id") == space_row.get("id")
                return False
            candidates = [c for c in candidates if _in_space(c)]

        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "List not found.")
        if len(candidates) > 1:
            return None, _err("CONFLICT", "listName is ambiguous; provide listId or additional scope.", matches=[m.get("id") for m in candidates])
        return candidates[0], None

    # --- auth context (ambient) ---
    # Find any active workspace that can satisfy the request once a list is resolved.
    # If store has no active workspaces at all, treat as unauthorized.
    workspaces = _load("workspaces.json")
    if not any(w.get("status") == "active" for w in workspaces):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context is available.")

    # --- validate provided update fields ---
    updatable = {
        "name": name,
        "content": content,
        "status": status,
        "archived": archived,
        "due_date": due_date,
        "priority": priority,
        "assignee_member_id": assigneeMemberId,
        "override_statuses": override_statuses,
    }
    provided_keys = [k for k, v in updatable.items() if v is not None]
    if len(provided_keys) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No updatable fields provided.")

    # types/constraints
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if content is not None and not isinstance(content, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content must be a string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted.")
    if archived is not None and not isinstance(archived, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be a boolean.")
    parsed_due = None
    if due_date is not None:
        parsed_due = _parse_dt(due_date)
        if parsed_due in ("INVALID_TYPE", "INVALID_FORMAT"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "due_date must be an ISO 8601 date-time string.")
    if priority is not None:
        if not isinstance(priority, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer.")
        if priority < 0 or priority > 4:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be between 0 and 4.")
    if assigneeMemberId is not None:
        if not isinstance(assigneeMemberId, str) or not re.match(r"^cu_usr_[0-9A-Z]{18,}$", assigneeMemberId):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assigneeMemberId is invalid.")
    if override_statuses is not None and not isinstance(override_statuses, list):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "override_statuses must be an array.")

    containers = _load("containers.json")
    members = _load("members.json")

    target, e = _resolve_list(containers)
    if e:
        _log("error", error_code=e["error"]["code"])
        return e

    # Workspace must be active
    ws = _resolve_workspace_context_for_container(target)
    if not ws:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context is available for this list.")

    # Validate assignee member reference if provided
    if assigneeMemberId is not None:
        m = next((mm for mm in members if mm.get("id") == assigneeMemberId and mm.get("workspace_id") == target.get("workspace_id")), None)
        if not m:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "assigneeMemberId does not reference a member in this workspace.")

    # Lifecycle transition validation if status change
    if status is not None and status != target.get("status"):
        cur = target.get("status")
        allowed = {"active": ["deleted"], "deleted": []}.get(cur, [])
        if status not in allowed:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}.")

    # Ensure it is a list
    if target.get("type") != "list":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "List not found.")

    # Apply changes (only provided fields)
    changed = False
    def _set(field, value):
        nonlocal changed
        if target.get(field) != value:
            target[field] = value
            changed = True

    if name is not None:
        _set("name", name)
    if content is not None:
        _set("content", content)
    if status is not None:
        _set("status", status)
    if archived is not None:
        _set("archived", archived)
    if due_date is not None:
        _set("due_date", parsed_due)
    if priority is not None:
        _set("priority", priority)
    if assigneeMemberId is not None:
        _set("assignee_member_id", assigneeMemberId)
    if override_statuses is not None:
        _set("override_statuses", override_statuses)

    if not changed:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No changes detected for provided fields.")

    target["updated_at"] = _now_iso()

    _save("containers.json", containers)
    _log("ok")
    return {"list": target}

def delete_list(listId=None, listName=None, folderId=None, spaceId=None, folderName=None, spaceName=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    if listId is None and listName is None:
        e = _err("VALIDATION_ERROR", "Provide listId or listName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if listId is not None and (not isinstance(listId, str) or not listId.strip()):
        e = _err("VALIDATION_ERROR", "listId must be a non-empty string when provided")
        _log("error", "VALIDATION_ERROR")
        return e
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        e = _err("VALIDATION_ERROR", "listName must be a non-empty string when provided")
        _log("error", "VALIDATION_ERROR")
        return e
    for fld, v in (("folderId", folderId), ("spaceId", spaceId), ("folderName", folderName), ("spaceName", spaceName)):
        if v is not None and (not isinstance(v, str) or not v.strip()):
            e = _err("VALIDATION_ERROR", f"{fld} must be a non-empty string when provided")
            _log("error", "VALIDATION_ERROR")
            return e

    containers = _load("containers.json")
    tasks = _load("tasks.json")
    activity = _load("task_activity.json")
    if not isinstance(containers, list):
        containers = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(activity, list):
        activity = []

    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("id")}

    def _resolve_space_id_by_name(space_name):
        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "space" and c.get("status") == "active" and c.get("name") == space_name]
        if len(candidates) == 1:
            return candidates[0].get("id"), None
        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "space not found", spaceName=space_name)
        return None, _err("CONFLICT", "spaceName is ambiguous", spaceName=space_name, matches=len(candidates))

    def _resolve_folder_id_by_name_in_space(folder_name, space_id):
        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "folder" and c.get("status") == "active" and c.get("parent_id") == space_id and c.get("name") == folder_name]
        if len(candidates) == 1:
            return candidates[0].get("id"), None
        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "folder not found", folderName=folder_name, spaceId=space_id)
        return None, _err("CONFLICT", "folderName is ambiguous within space", folderName=folder_name, spaceId=space_id, matches=len(candidates))

    # Determine list
    target_list = None
    if listId is not None:
        lid = listId.strip()
        c = cont_by_id.get(lid)
        if c and c.get("type") == "list" and c.get("status") == "active":
            target_list = c
        else:
            e = _err("NOT_FOUND", "list not found", listId=lid)
            _log("error", "NOT_FOUND")
            return e
    else:
        ln = listName.strip()

        space_scope_id = None
        if spaceId is not None:
            space_scope_id = spaceId.strip()
        elif spaceName is not None:
            space_scope_id, err = _resolve_space_id_by_name(spaceName.strip())
            if err:
                _log("error", err["error"]["code"])
                return err

        folder_scope_id = None
        if folderId is not None:
            folder_scope_id = folderId.strip()
        elif folderName is not None:
            if space_scope_id is None:
                e = _err("VALIDATION_ERROR", "folderName disambiguation requires spaceId or spaceName.")
                _log("error", "VALIDATION_ERROR")
                return e
            folder_scope_id, err = _resolve_folder_id_by_name_in_space(folderName.strip(), space_scope_id)
            if err:
                _log("error", err["error"]["code"])
                return err

        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == ln]

        if folder_scope_id is not None:
            candidates = [c for c in candidates if c.get("parent_id") == folder_scope_id]
        elif space_scope_id is not None:
            # list parent can be space or folder under that space
            def _in_space(cand):
                pid = cand.get("parent_id")
                if pid == space_scope_id:
                    return True
                parent = cont_by_id.get(pid)
                return bool(parent and parent.get("type") == "folder" and parent.get("parent_id") == space_scope_id)
            candidates = [c for c in candidates if _in_space(c)]

        if len(candidates) == 0:
            e = _err("NOT_FOUND", "list not found", listName=ln)
            _log("error", "NOT_FOUND")
            return e
        if len(candidates) > 1:
            e = _err("CONFLICT", "listName is ambiguous; provide listId to disambiguate.", listName=ln, matches=len(candidates))
            _log("error", "CONFLICT")
            return e
        target_list = candidates[0]

    now = _now()

    # Soft-delete list (container lifecycle)
    updated = 0
    for c in containers:
        if isinstance(c, dict) and c.get("id") == target_list.get("id"):
            if c.get("status") != "active":
                e = _err("INVALID_TRANSITION", "List is not active and cannot be deleted.", listId=target_list.get("id"), status=c.get("status"))
                _log("error", "INVALID_TRANSITION")
                return e
            c["status"] = "deleted"
            c["updated_at"] = now
            updated = 1
            break
    if updated != 1:
        e = _err("NOT_FOUND", "list not found for deletion", listId=target_list.get("id"))
        _log("error", "NOT_FOUND")
        return e

    # Delete tasks contained within it (soft-delete per task rule)
    deleted_tasks = 0
    deleted_activity = 0
    list_id = target_list.get("id")
    affected_task_ids = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("list_container_id") == list_id and t.get("status") == "active":
            t["status"] = "deleted"
            t["updated_at"] = now
            deleted_tasks += 1
            if t.get("id"):
                affected_task_ids.append(t.get("id"))
    if affected_task_ids:
        task_id_set = set(affected_task_ids)
        for a in activity:
            if isinstance(a, dict) and a.get("task_id") in task_id_set and a.get("status") == "active":
                a["status"] = "deleted"
                a["updated_at"] = now
                deleted_activity += 1

    _save("containers.json", containers)
    _save("tasks.json", tasks)
    _save("task_activity.json", activity)

    _log("ok", meta={"list_id": target_list.get("id"), "deleted_tasks": deleted_tasks, "deleted_activity": deleted_activity})
    return {"list_id": target_list.get("id"), "status": "deleted", "deleted_tasks": deleted_tasks, "deleted_activity_rows": deleted_activity}

def get_folder(folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_folder"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_log.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_log.json", logs)

    def _container_by_id(containers, cid):
        return next((c for c in containers if c.get("id") == cid), None)

    # Ambient auth: require at least one active workspace exists
    workspaces = _load("workspaces.json")
    if not any(w.get("status") == "active" for w in workspaces):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context is available.")

    containers = _load("containers.json")

    if folderId is None and folderName is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either folderId or folderName must be provided.")

    if folderId is not None:
        if not isinstance(folderId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", folderId):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "folderId is invalid.")
        f = _container_by_id(containers, folderId)
        if not f or f.get("type") != "folder" or f.get("status") != "active":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Folder not found.")
        # workspace active?
        ws = next((w for w in workspaces if w.get("id") == f.get("workspace_id") and w.get("status") == "active"), None)
        if not ws:
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active workspace context is available for this folder.")
        _log("ok")
        return {"folder": f}

    # Resolve by name within a space
    if folderName is None or not isinstance(folderName, str) or not folderName.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folderName is invalid.")
    if spaceId is None and spaceName is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Resolving folderName requires spaceId or spaceName for disambiguation.")
    if spaceId is not None and (not isinstance(spaceId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", spaceId)):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spaceId is invalid.")
    if spaceName is not None and (not isinstance(spaceName, str) or not spaceName.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spaceName is invalid.")

    # Resolve space
    space = None
    if spaceId is not None:
        space = _container_by_id(containers, spaceId)
        if not space or space.get("type") != "space" or space.get("status") != "active":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Space not found.")
    else:
        sm = [c for c in containers if c.get("type") == "space" and c.get("status") == "active" and c.get("name") == spaceName]
        if len(sm) == 0:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Space not found.")
        if len(sm) > 1:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "spaceName is ambiguous; provide spaceId.", matches=[m.get("id") for m in sm])
        space = sm[0]

    # workspace active?
    ws = next((w for w in workspaces if w.get("id") == space.get("workspace_id") and w.get("status") == "active"), None)
    if not ws:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context is available for this space.")

