        if isinstance(reqlog2, list) and reqlog2:
            # update last matching started row
            for i in range(len(reqlog2) - 1, -1, -1):
                r = reqlog2[i]
                if isinstance(r, dict) and r.get("tool") == "update_folder" and r.get("status") == "started":
                    r["status"] = status
                    r["latency_ms"] = int((time.time() - t0) * 1000)
                    r["ts_end"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    break
            _save(reqlog_name, reqlog2)
        return resp

    try:
        # Validate updatable fields
        if name is None and override_statuses is None:
            return _finish(_err("VALIDATION_ERROR", "No updatable fields provided; supply at least one of: name, override_statuses."), "error")

        if folderId is not None:
            if not isinstance(folderId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", folderId):
                return _finish(_err("VALIDATION_ERROR", "folderId is invalid."), "error")
        if folderName is not None and (not isinstance(folderName, str) or folderName.strip() == ""):
            return _finish(_err("VALIDATION_ERROR", "folderName must be a non-empty string when provided."), "error")
        if spaceId is not None:
            if not isinstance(spaceId, str) or not re.match(r"^cu_cnt_[0-9A-Z]{18,}$", spaceId):
                return _finish(_err("VALIDATION_ERROR", "spaceId is invalid."), "error")
        if spaceName is not None and (not isinstance(spaceName, str) or spaceName.strip() == ""):
            return _finish(_err("VALIDATION_ERROR", "spaceName must be a non-empty string when provided."), "error")
        if name is not None and (not isinstance(name, str) or name.strip() == ""):
            return _finish(_err("VALIDATION_ERROR", "name must be a non-empty string when provided."), "error")
        if override_statuses is not None and not isinstance(override_statuses, list):
            return _finish(_err("VALIDATION_ERROR", "override_statuses must be an array when provided."), "error")

        containers = _load("containers.json")
        if not isinstance(containers, list):
            return _finish(_err("NOT_FOUND", "Datastore unavailable."), "error")

        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}

        def _resolve_space():
            if spaceId is None and spaceName is None:
                return None
            if spaceId is not None:
                for c in containers:
                    if isinstance(c, dict) and c.get("id") == spaceId and c.get("type") == "space" and c.get("status") == "active":
                        return c
                return "NOT_FOUND"
            # by name
            matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "space" and c.get("status") == "active" and c.get("name") == spaceName]
            if len(matches) == 0:
                return "NOT_FOUND"
            if len(matches) > 1:
                return "CONFLICT"
            return matches[0]

        # Resolve folder
        folder = None
        if folderId is not None:
            for c in containers:
                if isinstance(c, dict) and c.get("id") == folderId and c.get("type") == "folder" and c.get("status") == "active":
                    folder = c
                    break
            if folder is None:
                return _finish(_err("NOT_FOUND", "Folder not found."), "error")
        else:
            if folderName is None:
                return _finish(_err("VALIDATION_ERROR", "Provide folderId or folderName."), "error")

            # Folder name resolution requires space scope (per rules)
            sp = _resolve_space()
            if sp is None:
                return _finish(_err("VALIDATION_ERROR", "spaceId or spaceName is required to resolve folderName."), "error")
            if sp == "NOT_FOUND":
                return _finish(_err("NOT_FOUND", "Space not found."), "error")
            if sp == "CONFLICT":
                return _finish(_err("CONFLICT", "spaceName is ambiguous; use spaceId."), "error")

            matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "folder" and c.get("status") == "active" and c.get("name") == folderName and c.get("parent_id") == sp.get("id")]
            if len(matches) == 0:
                return _finish(_err("NOT_FOUND", "Folder not found in the resolved space."), "error")
            if len(matches) > 1:
                return _finish(_err("CONFLICT", "folderName is ambiguous within the resolved space; use folderId."), "error")
            folder = matches[0]

        # Check workspace state (must exist and not deleted)
        ws = ws_by_id.get(folder.get("workspace_id"))
        if not ws or ws.get("status") != "active":
            return _finish(_err("UNAUTHORIZED", "No accessible active workspace can serve this request."), "error")

        # Apply changes
        changed = False
        if name is not None and name != folder.get("name"):
            folder["name"] = name
            changed = True
        if override_statuses is not None:
            # Replace semantics
            if override_statuses != folder.get("override_statuses"):
                folder["override_statuses"] = override_statuses
                changed = True

        if not changed:
            return _finish(_err("VALIDATION_ERROR", "No changes detected; provide at least one field with a different value."), "error")

        folder["updated_at"] = now
        _save("containers.json", containers)

        return _finish({"folder": folder}, "ok")
    except ValueError as e:
        return _finish(_err("VALIDATION_ERROR", str(e)), "error")
    except Exception:
        return _finish(_err("NOT_FOUND", "Unexpected server error."), "error")

def delete_folder(folderId, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_folder"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    if not isinstance(folderId, str) or not folderId.strip():
        e = _err("VALIDATION_ERROR", "folderId is required and must be a non-empty string.")
        _log("error", "VALIDATION_ERROR")
        return e
    fid = folderId.strip()

    for fld, v in (("folderName", folderName), ("spaceId", spaceId), ("spaceName", spaceName)):
        if v is not None and (not isinstance(v, str) or not v.strip()):
            e = _err("VALIDATION_ERROR", f"{fld} must be a non-empty string when provided.")
            _log("error", "VALIDATION_ERROR")
            return e

    containers = _load("containers.json")
    tasks = _load("tasks.json")
    activity = _load("task_activity.json")
    if not isinstance(containers, list):
        containers = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(activity, list):
        activity = []

    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("id")}

    folder = cont_by_id.get(fid)
    if not folder or folder.get("type") != "folder" or folder.get("status") != "active":
        e = _err("NOT_FOUND", "folder not found", folderId=fid)
        _log("error", "NOT_FOUND")
        return e

    # Optional cross-check scope if provided
    if spaceId is not None and folder.get("parent_id") != spaceId.strip():
        e = _err("NOT_FOUND", "folder not found in the specified space scope", folderId=fid, spaceId=spaceId.strip())
        _log("error", "NOT_FOUND")
        return e
    if spaceName is not None:
        # resolve space by name and ensure folder under it
        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "space" and c.get("status") == "active" and c.get("name") == spaceName.strip()]
        if len(candidates) == 0:
            e = _err("NOT_FOUND", "space not found", spaceName=spaceName.strip())
            _log("error", "NOT_FOUND")
            return e
        if len(candidates) > 1:
            e = _err("CONFLICT", "spaceName is ambiguous", spaceName=spaceName.strip(), matches=len(candidates))
            _log("error", "CONFLICT")
            return e
        if folder.get("parent_id") != candidates[0].get("id"):
            e = _err("NOT_FOUND", "folder not found in the specified space scope", folderId=fid, spaceName=spaceName.strip())
            _log("error", "NOT_FOUND")
            return e

    if folderName is not None and folder.get("name") != folderName.strip():
        e = _err("NOT_FOUND", "folder not found for folderName match", folderId=fid, folderName=folderName.strip())
        _log("error", "NOT_FOUND")
        return e

    now = _now()

    # Soft-delete folder
    updated = 0
    for c in containers:
        if isinstance(c, dict) and c.get("id") == fid:
            if c.get("status") != "active":
                e = _err("INVALID_TRANSITION", "Folder is not active and cannot be deleted.", folderId=fid, status=c.get("status"))
                _log("error", "INVALID_TRANSITION")
                return e
            c["status"] = "deleted"
            c["updated_at"] = now
            updated = 1
            break
    if updated != 1:
        e = _err("NOT_FOUND", "folder not found for deletion", folderId=fid)
        _log("error", "NOT_FOUND")
        return e

    # Soft-delete lists under folder, and tasks within those lists, plus their activity
    list_ids = [c.get("id") for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active" and c.get("parent_id") == fid]
    deleted_lists = 0
    for c in containers:
        if isinstance(c, dict) and c.get("id") in set(list_ids):
            c["status"] = "deleted"
            c["updated_at"] = now
            deleted_lists += 1

    deleted_tasks = 0
    affected_task_ids = []
    list_id_set = set(list_ids)
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("list_container_id") in list_id_set and t.get("status") == "active":
            t["status"] = "deleted"
            t["updated_at"] = now
            deleted_tasks += 1
            if t.get("id"):
                affected_task_ids.append(t.get("id"))

    deleted_activity = 0
    if affected_task_ids:
        task_id_set = set(affected_task_ids)
        for a in activity:
            if isinstance(a, dict) and a.get("task_id") in task_id_set and a.get("status") == "active":
                a["status"] = "deleted"
                a["updated_at"] = now
                deleted_activity += 1

    _save("containers.json", containers)
    _save("tasks.json", tasks)
    _save("task_activity.json", activity)

    _log("ok", meta={"folder_id": fid, "deleted_lists": deleted_lists, "deleted_tasks": deleted_tasks, "deleted_activity": deleted_activity})
    return {"folder_id": fid, "status": "deleted", "deleted_lists": deleted_lists, "deleted_tasks": deleted_tasks, "deleted_activity_rows": deleted_activity}

