def add_tag_to_task(taskId, taskName=None, listName=None, listId=None, tagName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_tag_to_task"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status_s, error_code=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None,
            **({"error_code": error_code} if error_code else {}),
            "meta": meta or {},
        })
        _save("request_log.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}{''.join(secrets.choice(alphabet) for _ in range(22))}"

    if tagName is None or not isinstance(tagName, str) or not tagName.strip():
        e = _err("VALIDATION_ERROR", "tagName is required and must be a non-empty string.")
        _log("error", "VALIDATION_ERROR")
        return e
    tag = tagName.strip()

    # taskId is positional; allow None only if taskName is provided
    if taskId is None and taskName is None:
        e = _err("VALIDATION_ERROR", "Provide taskId or taskName.")
        _log("error", "VALIDATION_ERROR")
        return e
    if taskId is not None and (not isinstance(taskId, str) or not taskId.strip()):
        e = _err("VALIDATION_ERROR", "taskId must be a non-empty string when provided.")
        _log("error", "VALIDATION_ERROR")
        return e

    for fld, v in (("taskName", taskName), ("listName", listName), ("listId", listId), ("spaceId", spaceId), ("spaceName", spaceName)):
        if v is not None and (not isinstance(v, str) or not v.strip()):
            e = _err("VALIDATION_ERROR", f"{fld} must be a non-empty string when provided.")
            _log("error", "VALIDATION_ERROR")
            return e

    tasks = _load("tasks.json")
    containers = _load("containers.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(containers, list):
        containers = []
    if not isinstance(activity, list):
        activity = []

    cont_by_id = {c.get("id"): c for c in containers if isinstance(c, dict) and c.get("id")}

    def _space_for_task(task_row):
        # task -> list -> (folder?) -> space
        lid = task_row.get("list_container_id")
        lst = cont_by_id.get(lid)
        if not lst:
            return None
        pid = lst.get("parent_id")
        parent = cont_by_id.get(pid)
        if parent and parent.get("type") == "folder":
            return cont_by_id.get(parent.get("parent_id"))
        if parent and parent.get("type") == "space":
            return parent
        # if list parent is space id directly but not found, return None
        return parent if parent and parent.get("type") == "space" else None

    def _resolve_task():
        # use business rule for taskId matching clickup_task_id OR custom_task_id; detect ambiguity
        if taskId is not None and taskId.strip():
            tid = taskId.strip()
            clickup_hits = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("clickup_task_id") == tid]
            custom_hits = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("custom_task_id") == tid]
            internal_hits = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("id") == tid]
            ids = {t.get("id") for t in (clickup_hits + custom_hits + internal_hits) if t.get("id")}
            if len(ids) == 0:
                return None, _err("NOT_FOUND", "task not found", taskId=tid)
            if len(ids) > 1:
                return None, _err("CONFLICT", "taskId is ambiguous (matches multiple tasks).", taskId=tid, matches=len(ids))
            return (clickup_hits + custom_hits + internal_hits)[0], None

        tn = taskName.strip()
        # scope by listId/listName if provided; otherwise ambiguity error if multiple
        candidate_tasks = [t for t in tasks if isinstance(t, dict) and t.get("status") == "active" and t.get("name") == tn]
        if listId is not None:
            lid = listId.strip()
            candidate_tasks = [t for t in candidate_tasks if t.get("list_container_id") == lid]
        elif listName is not None:
            ln = listName.strip()
            lists = [c for c in containers if isinstance(c, dict) and c.get("type") == "list" and c.get("status") == "active" and c.get("name") == ln]
            if len(lists) == 0:
                return None, _err("NOT_FOUND", "list not found for listName scope", listName=ln)
            if len(lists) > 1:
                return None, _err("CONFLICT", "listName is ambiguous; cannot resolve taskName.", listName=ln, matches=len(lists))
            candidate_tasks = [t for t in candidate_tasks if t.get("list_container_id") == lists[0].get("id")]

        if len(candidate_tasks) == 0:
            return None, _err("NOT_FOUND", "task not found", taskName=tn)
        if len(candidate_tasks) > 1:
            return None, _err("CONFLICT", "taskName is ambiguous; provide taskId or list scope.", taskName=tn, matches=len(candidate_tasks))
        return candidate_tasks[0], None

    task, err = _resolve_task()
    if err:
        _log("error", err["error"]["code"])
        return err

    space = _space_for_task(task)
    if not space or space.get("type") != "space" or space.get("status") != "active":
        e = _err("NOT_FOUND", "Could not resolve task's space for tag validation.", task_id=task.get("id"))
        _log("error", "NOT_FOUND")
        return e

    # Optional validation against provided space scope
    if spaceId is not None and space.get("id") != spaceId.strip():
        e = _err("NOT_FOUND", "Task is not in the specified space.", task_id=task.get("id"), spaceId=spaceId.strip())
        _log("error", "NOT_FOUND")
        return e
    if spaceName is not None and space.get("name") != spaceName.strip():
        e = _err("NOT_FOUND", "Task is not in the specified spaceName.", task_id=task.get("id"), spaceName=spaceName.strip())
        _log("error", "NOT_FOUND")
        return e

    # Tag must exist as space_tag in that space
    wsid = task.get("workspace_id")
    space_tag = None
    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "active":
            continue
        if a.get("kind") == "space_tag" and a.get("workspace_id") == wsid and a.get("space_container_id") == space.get("id") and a.get("tag_name") == tag:
            space_tag = a
            break
    if not space_tag:
        e = _err("NOT_FOUND", "Tag does not exist in the task's space. Create the space tag first.", tagName=tag, spaceId=space.get("id"))
        _log("error", "NOT_FOUND")
        return e

    # Prevent duplicates (unique constraint)
    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "active" and a.get("kind") == "task_tag" and a.get("workspace_id") == wsid and a.get("task_id") == task.get("id") and a.get("tag_name") == tag:
            # idempotent success
            _log("ok", meta={"task_id": task.get("id"), "tagName": tag, "already_present": True})
            return {"task_id": task.get("id"), "tag_name": tag, "status": "active", "already_present": True}

    now = _now()
    new_row = {
        "id": _gen_id("cu_act_"),
        "workspace_id": wsid,
        "task_id": task.get("id"),
        "space_container_id": None,
        "kind": "task_tag",
        "clickup_id": None,
        "author_member_id": None,
        "assignee_member_id": None,
        "notify_all": None,
        "body_text": None,
        "attachment_filename": None,
        "attachment_source_type": None,
        "attachment_url": None,
        "attachment_size_bytes": None,
        "tag_name": tag,
        "tag_color": space_tag.get("tag_color"),
        "billable": None,
        "time_entry_description": None,
        "time_entry_tags": None,
        "start_time": None,
        "end_time": None,
        "duration_ms": None,
        "running": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    activity.append(new_row)
    _save("task_activity.json", activity)

    _log("ok", meta={"activity_id": new_row["id"], "task_id": task.get("id"), "tagName": tag})
    return {"task_tag": new_row}

def remove_tag_from_task(workspaceId, tagName, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    def _log(endpoint, status, workspace_id=None, details=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": _gen_id("cu_req_"),
            "ts": _now(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "latency_ms": latency_ms,
            "details": details or {},
        }
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_log.json", logs)

    started = time.time()
    endpoint = "remove_tag_from_task"

    # Validate inputs
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId or ""):
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "workspaceId"}, started)
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]{18,}$", field="workspaceId")
    if not isinstance(tagName, str) or not tagName.strip():
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "tagName"}, started)
        return _err("VALIDATION_ERROR", "tagName must be a non-empty string", field="tagName")

    if taskId is None and taskName is None:
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "taskId/taskName"}, started)
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required", field="taskId|taskName")
    if taskId is not None:
        if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]{18,}$", taskId or ""):
            _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "taskId"}, started)
            return _err("VALIDATION_ERROR", "taskId must match ^cu_tsk_[0-9A-Z]{18,}$", field="taskId")
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "taskName"}, started)
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string", field="taskName")
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "listName"}, started)
        return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided", field="listName")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if not ws or ws.get("status") != "active":
        _log(endpoint, "NOT_FOUND", workspaceId, {"workspaceId": workspaceId}, started)
        return _err("NOT_FOUND", "Workspace not found or not active", workspaceId=workspaceId)

    containers = _load("containers.json")
    tasks = _load("tasks.json")
    activity = _load("task_activity.json")

    def _find_list_by_name(name):
        name_l = name.strip().lower()
        matches = [
            c for c in containers
            if isinstance(c, dict)
            and c.get("workspace_id") == workspaceId
            and c.get("type") == "list"
            and c.get("status") == "active"
            and isinstance(c.get("name"), str)
            and c.get("name").strip().lower() == name_l
        ]
        return matches

    def _resolve_task():
        # taskId resolution matches clickup_task_id OR custom_task_id; ambiguity error if both match different tasks.
        active_tasks = [
            t for t in tasks
            if isinstance(t, dict)
            and t.get("workspace_id") == workspaceId
            and t.get("status") == "active"
        ]

        if taskId is not None:
            by_clickup = [t for t in active_tasks if t.get("clickup_task_id") == taskId]
            by_custom = [t for t in active_tasks if t.get("custom_task_id") == taskId]
            # If both match and point to different tasks => ambiguity
            ids = {t.get("id") for t in (by_clickup + by_custom)}
            if len(ids) > 1:
                return _err("CONFLICT", "taskId is ambiguous: matches multiple tasks by clickup_task_id/custom_task_id", taskId=taskId, matches=list(ids))
            if len(ids) == 0:
                return _err("NOT_FOUND", "Task not found", taskId=taskId)
            return next(t for t in (by_clickup + by_custom) if t.get("id") in ids)

        # taskName resolution: if listName provided, scope to that list; else search workspace and fail if multiple matches.
        name_l = taskName.strip().lower()
        scoped_list_ids = None
        if listName is not None:
            list_matches = _find_list_by_name(listName)
            if len(list_matches) == 0:
                return _err("NOT_FOUND", "List not found for provided listName", listName=listName)
            if len(list_matches) > 1:
                return _err("CONFLICT", "listName is ambiguous: multiple active lists have this name", listName=listName, listContainerIds=[c.get("id") for c in list_matches])
            scoped_list_ids = {list_matches[0].get("id")}

        name_matches = []
        for t in active_tasks:
            if not isinstance(t.get("name"), str):
                continue
            if t.get("name").strip().lower() != name_l:
                continue
            if scoped_list_ids is not None and t.get("list_container_id") not in scoped_list_ids:
                continue
            name_matches.append(t)

        if len(name_matches) == 0:
            return _err("NOT_FOUND", "Task not found by taskName", taskName=taskName, listName=listName)
        if len(name_matches) > 1:
            return _err("CONFLICT", "taskName is ambiguous: multiple active tasks match; provide taskId or listName to disambiguate", taskName=taskName, matches=[t.get("id") for t in name_matches])
        return name_matches[0]

    resolved = _resolve_task()
    if isinstance(resolved, dict) and resolved.get("error"):
        _log(endpoint, resolved["error"]["code"], workspaceId, {"tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName}, started)
        return resolved
    task = resolved

    # Soft-delete task_tag association (must not delete underlying space_tag)
    tag_l = tagName.strip().lower()
    candidates = [
        a for a in activity
        if isinstance(a, dict)
        and a.get("workspace_id") == workspaceId
        and a.get("kind") == "task_tag"
        and a.get("task_id") == task.get("id")
        and a.get("status") == "active"
        and isinstance(a.get("tag_name"), str)
        and a.get("tag_name").strip().lower() == tag_l
    ]
    if len(candidates) == 0:
        _log(endpoint, "NOT_FOUND", workspaceId, {"task_id": task.get("id"), "tagName": tagName}, started)
        return _err("NOT_FOUND", "Tag is not assigned to this task", taskId=task.get("id"), tagName=tagName)

    now = _now()
    affected_ids = []
    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("id") in {c.get("id") for c in candidates}:
            # lifecycle transition active -> deleted
            if a.get("status") != "active":
                continue
            a["status"] = "deleted"
            a["updated_at"] = now
            affected_ids.append(a.get("id"))

    if not affected_ids:
        _log(endpoint, "NOT_FOUND", workspaceId, {"task_id": task.get("id"), "tagName": tagName}, started)
        return _err("NOT_FOUND", "Tag-task association not found", taskId=task.get("id"), tagName=tagName)

    _save("task_activity.json", activity)

    resp = {
        "workspace_id": workspaceId,
        "task": task,
        "tag_name": tagName,
        "removed": [{"id": _id} for _id in affected_ids],
        "removed_count": len(affected_ids),
    }
    _log(endpoint, "OK", workspaceId, {"removed_count": len(affected_ids)}, started)
    return resp

def get_workspace_members(workspaceId, status=None, role=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    def _log(endpoint, status_s, workspace_id=None, details=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": _gen_id("cu_req_"),
            "ts": _now(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "details": details or {},
        }
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_log.json", logs)

    started = time.time()
    endpoint = "get_workspace_members"

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId or ""):
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "workspaceId"}, started)
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]{18,}$", field="workspaceId")

    if status is not None and status not in ("active", "inactive"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "status"}, started)
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "inactive"])
    if role is not None and role not in ("owner", "admin", "member", "guest"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "role"}, started)
        return _err("VALIDATION_ERROR", "Invalid role", field="role", allowed=["owner", "admin", "member", "guest"])
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "limit"}, started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if sort is None:
        sort = "full_name"
    if sort not in ("full_name", "username", "email", "created_at", "updated_at"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "sort"}, started)
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "order"}, started)
        return _err("VALIDATION_ERROR", "Invalid order", field="order")

    # Workspace existence
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if not ws:
        _log(endpoint, "NOT_FOUND", workspaceId, {"workspaceId": workspaceId}, started)
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    members = _load("members.json")
    rows = [
        m for m in members
        if isinstance(m, dict) and m.get("workspace_id") == workspaceId
    ]
    if status is not None:
        rows = [m for m in rows if m.get("status") == status]
    if role is not None:
        rows = [m for m in rows if m.get("role") == role]

    def _sort_key(m):
        v = m.get(sort)
        if v is None:
            return ""
        if isinstance(v, str):
            return v.lower()
        return v

    reverse = (order == "desc")
    rows.sort(key=lambda m: (_sort_key(m), (m.get("id") or "")), reverse=reverse)

    # Cursor: opaque base64 of "offset:<n>"
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "cursor"}, started)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            decoded_s = decoded.decode("utf-8")
            if not decoded_s.startswith("offset:"):
                _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "cursor"}, started)
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            offset = int(decoded_s.split(":", 1)[1])
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "cursor"}, started)
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "workspace_id": workspaceId,
        "members": page,
        "page": {
            "limit": limit,
            "cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
        "sort": {"field": sort, "order": order},
        "filters": {"status": status, "role": role},
    }
    _log(endpoint, "OK", workspaceId, {"returned": len(page), "total": total, "has_more": has_more}, started)
    return resp

def find_member_by_name(workspaceId, query, match=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    def _log(endpoint, status_s, workspace_id=None, details=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": _gen_id("cu_req_"),
            "ts": _now(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "details": details or {},
        }
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_log.json", logs)

    started = time.time()
    endpoint = "find_member_by_name"

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId or ""):
        _log(endpoint, "VALIDATION_ERROR", None, {"field": "workspaceId"}, started)
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]{18,}$", field="workspaceId")
    if not isinstance(query, str) or not query.strip():
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "query"}, started)
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")

    if match is None:
        match = "contains"
    if match not in ("exact", "contains"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "match"}, started)
        return _err("VALIDATION_ERROR", "Invalid match", field="match", allowed=["exact", "contains"])
    if status is not None and status not in ("active", "inactive"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "status"}, started)
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "inactive"])

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if not ws:
        _log(endpoint, "NOT_FOUND", workspaceId, {"workspaceId": workspaceId}, started)
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    members = _load("members.json")
    rows = [m for m in members if isinstance(m, dict) and m.get("workspace_id") == workspaceId]
    if status is not None:
        rows = [m for m in rows if m.get("status") == status]

    q = query.strip()
    ql = q.lower()

    def _fields(m):
        return [
            (m.get("full_name") or ""),
            (m.get("username") or ""),
            (m.get("email") or ""),
        ]

    matches = []
    for m in rows:
        fields = _fields(m)
        if match == "exact":
            if any(isinstance(f, str) and f.strip().lower() == ql for f in fields):
                matches.append(m)
        else:
            if any(isinstance(f, str) and ql in f.strip().lower() for f in fields):
                matches.append(m)

    # Tool says: return member if found, else null (no ambiguity guidance here; pick best deterministic: exact email/username/full_name then lowest updated_at/created_at/id)
    result = None
    if matches:
        def _score(m):
            full = (m.get("full_name") or "").strip().lower()
            user = (m.get("username") or "").strip().lower()
            email = (m.get("email") or "").strip().lower()
            exactness = 0
            if email == ql:
                exactness = 3
            elif user == ql:
                exactness = 2
            elif full == ql:
                exactness = 1
            # prefer active over inactive if status not constrained
            active_bonus = 1 if (status is None and m.get("status") == "active") else 0
            # stable tie-breakers
            return (-exactness, -active_bonus, (m.get("updated_at") or ""), (m.get("created_at") or ""), (m.get("id") or ""))
        matches.sort(key=_score)
        result = matches[0]

    resp = {"workspace_id": workspaceId, "query": query, "match": match, "status": status, "member": result}
    _log(endpoint, "OK", workspaceId, {"found": bool(result), "candidates": len(matches)}, started)
    return resp

