    if status is not None and status not in ("active", "inactive"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "status"}, started)
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "inactive"])

    if onAmbiguous is None:
        onAmbiguous = "error"
    if onAmbiguous not in ("error", "first_match"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "onAmbiguous"}, started)
        return _err("VALIDATION_ERROR", "Invalid onAmbiguous", field="onAmbiguous", allowed=["error", "first_match"])

    if onNotFound is None:
        onNotFound = "error"
    if onNotFound not in ("error", "skip"):
        _log(endpoint, "VALIDATION_ERROR", workspaceId, {"field": "onNotFound"}, started)
        return _err("VALIDATION_ERROR", "Invalid onNotFound", field="onNotFound", allowed=["error", "skip"])

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if not ws:
        _log(endpoint, "NOT_FOUND", workspaceId, {"workspaceId": workspaceId}, started)
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    members = _load("members.json")
    rows = [m for m in members if isinstance(m, dict) and m.get("workspace_id") == workspaceId]
    if status is not None:
        rows = [m for m in rows if m.get("status") == status]

    def _member_matches(m, token_lower):
        full = (m.get("full_name") or "").strip().lower()
        user = (m.get("username") or "").strip().lower()
        email = (m.get("email") or "").strip().lower()
        return token_lower == full or token_lower == user or token_lower == email

    def _member_contains(m, token_lower):
        full = (m.get("full_name") or "").strip().lower()
        user = (m.get("username") or "").strip().lower()
        email = (m.get("email") or "").strip().lower()
        return (token_lower in full) or (token_lower in user) or (token_lower in email)

    resolved_user_ids = []
    results = []
    errors = []

    for idx, token in enumerate(assignees):
        t = token.strip()
        tl = t.lower()

        exact = [m for m in rows if _member_matches(m, tl)]
        contains = exact if exact else [m for m in rows if _member_contains(m, tl)]
        matches = contains

        if not matches:
            if onNotFound == "skip":
                results.append({"input": token, "status": "skipped_not_found"})
                continue
            err = {"input": token, "code": "NOT_FOUND", "message": "Assignee not found"}
            errors.append(err)
            continue

        # If multiple matches and exact match exists among them, reduce to exacts
        exacts = [m for m in matches if _member_matches(m, tl)]
        if exacts:
            matches = exacts

        if len(matches) > 1 and onAmbiguous == "error":
            errors.append({
                "input": token,
                "code": "CONFLICT",
                "message": "Assignee is ambiguous",
                "matches": [{"id": m.get("id"), "clickup_user_id": m.get("clickup_user_id"), "full_name": m.get("full_name"), "username": m.get("username"), "email": m.get("email")} for m in matches[:10]],
            })
            continue

        # Deterministic first_match: prefer active, then exact email/username/full_name, then updated_at/created_at/id
        def _pick_score(m):
            full = (m.get("full_name") or "").strip().lower()
            user = (m.get("username") or "").strip().lower()
            email = (m.get("email") or "").strip().lower()
            exactness = 0
            if email == tl:
                exactness = 3
            elif user == tl:
                exactness = 2
            elif full == tl:
                exactness = 1
            active_bonus = 1 if (status is None and m.get("status") == "active") else 0
            return (-active_bonus, -exactness, (m.get("updated_at") or ""), (m.get("created_at") or ""), (m.get("id") or ""))

        matches.sort(key=_pick_score)
        chosen = matches[0]
        cu_uid = chosen.get("clickup_user_id")
        if not isinstance(cu_uid, str) or not cu_uid:
            errors.append({"input": token, "code": "CONFLICT", "message": "Matched member has no clickup_user_id"})
            continue

        resolved_user_ids.append(cu_uid)
        results.append({
            "input": token,
            "status": "resolved",
            "member": {
                "id": chosen.get("id"),
                "clickup_user_id": cu_uid,
                "full_name": chosen.get("full_name"),
                "username": chosen.get("username"),
                "email": chosen.get("email"),
                "role": chosen.get("role"),
                "status": chosen.get("status"),
            },
        })

    if errors and onNotFound == "error":
        _log(endpoint, "NOT_FOUND", workspaceId, {"errors": errors, "resolved": len(resolved_user_ids)}, started)
        return _err("NOT_FOUND", "One or more assignees could not be resolved", errors=errors, resolved_user_ids=resolved_user_ids)

    if errors and any(e.get("code") == "CONFLICT" for e in errors):
        _log(endpoint, "CONFLICT", workspaceId, {"errors": errors, "resolved": len(resolved_user_ids)}, started)
        return _err("CONFLICT", "One or more assignees are ambiguous", errors=errors, resolved_user_ids=resolved_user_ids)

    resp = {
        "workspace_id": workspaceId,
        "assignee_clickup_user_ids": resolved_user_ids,
        "results": results,
        "errors": errors,
    }
    _log(endpoint, "OK", workspaceId, {"resolved": len(resolved_user_ids), "errors": len(errors)}, started)
    return resp

def get_whoami(includeQuota=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0264000" if __import__("os").path.isdir("./environment_mix/0264000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- validate inputs
    if includeQuota is not None and not isinstance(includeQuota, bool):
        return _err("VALIDATION_ERROR", "includeQuota must be a boolean when provided.")

    # --- request/audit logging + rate/quota enforcement (best-effort; if no schema file exists, continue)
    endpoint = "get_whoami"
    request_logs_file = "request_logs.json"
    usage_file = "usage_counters.json"

    def _append_log(status, credential_id=None, workspace_id=None, reason=None, rate_limited=False):
        logs = _load(request_logs_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "workspace_id": workspace_id,
            "status": status,
            "reason": reason,
            "rate_limited": bool(rate_limited),
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save(request_logs_file, logs)

    def _get_rate_policy():
        # If vendor store has a policy row, use it; else default to reasonable local limits.
        pol = {"per_minute": 120, "per_day": 5000}
        policies = _load("rate_limits.json")
        if isinstance(policies, dict):
            # allow {"per_minute":..., "per_day":...}
            pm = policies.get("per_minute")
            pd = policies.get("per_day")
            if isinstance(pm, int) and pm > 0:
                pol["per_minute"] = pm
            if isinstance(pd, int) and pd > 0:
                pol["per_day"] = pd
        elif isinstance(policies, list):
            # allow [{"endpoint":"get_whoami",...}] or [{"default":true,...}]
            chosen = None
            for r in policies:
                if isinstance(r, dict) and r.get("endpoint") == endpoint:
                    chosen = r
                    break
            if chosen is None:
                for r in policies:
                    if isinstance(r, dict) and r.get("default") is True:
                        chosen = r
                        break
            if isinstance(chosen, dict):
                pm = chosen.get("per_minute")
                pd = chosen.get("per_day")
                if isinstance(pm, int) and pm > 0:
                    pol["per_minute"] = pm
                if isinstance(pd, int) and pd > 0:
                    pol["per_day"] = pd
        return pol

    def _count_in_window(logs, since_iso, credential_id):
        if not isinstance(logs, list):
            return 0
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = r.get("created_at")
            if isinstance(ts, str) and ts >= since_iso:
                c += 1
        return c

    def _iso_minus(seconds):
        dt = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=seconds)
        return dt.isoformat() + "Z"

    def _iso_day_start():
        dt = datetime.datetime.utcnow().replace(microsecond=0)
        dt = dt.replace(hour=0, minute=0, second=0)
        return dt.isoformat() + "Z"

    # --- Authentication: explicit credential parameter does not exist for this tool.
    # Ambient auth per contract: locate ANY viable identity in the store; refuse only if none exist.
    workspaces = _load("workspaces.json")
    members = _load("members.json")
    credentials = _load("credentials.json")
    api_keys = _load("api_keys.json")
    tokens = _load("tokens.json")
    sessions = _load("sessions.json")

    # Helper: pick a "credential-like" row if present; otherwise operate without one but still must have an identity.
    resolved = {
        "credential": None,
        "workspace": None,
        "member": None,
        "scopes": None
    }

    def _is_active_workspace(w):
        return isinstance(w, dict) and w.get("status") == "active"

    def _find_member_for_workspace(workspace_id):
        if not isinstance(members, list):
            return None
        # Prefer owner/admin active
        best = None
        for m in members:
            if not isinstance(m, dict):
                continue
            if m.get("workspace_id") != workspace_id:
                continue
            if m.get("status") != "active":
                continue
            role = m.get("role")
            if role in ("owner", "admin"):
                return m
            if best is None:
                best = m
        return best

    # Try to resolve from stored credential stores if they exist, else fallback to any active workspace+member.
    # Since no token param, the "presented token" cannot be matched directly; we resolve a serving identity.
    candidate_workspaces = [w for w in workspaces if _is_active_workspace(w)] if isinstance(workspaces, list) else []
    if not candidate_workspaces:
        _append_log(status="unauthorized", reason="no_active_workspace")
        return _err("UNAUTHORIZED", "Missing/invalid credentials (no active workspace identity available).")

    # Prefer a credential record that is linked to an active workspace and grants scopes.
    # Accept various common schemas: credential rows may contain workspace_id/team_id/scopes/status.
    cred_row = None
    if isinstance(credentials, list):
        for c in credentials:
            if not isinstance(c, dict):
                continue
            if c.get("status") not in (None, "active"):
                continue
            ws_id = c.get("workspace_id")
            if ws_id and any(w.get("id") == ws_id for w in candidate_workspaces):
                cred_row = c
                break
    if cred_row is None and isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") not in (None, "active"):
                continue
            ws_id = k.get("workspace_id")
            if ws_id and any(w.get("id") == ws_id for w in candidate_workspaces):
                cred_row = k
                break
    if cred_row is None and isinstance(tokens, list):
        for k in tokens:
            if not isinstance(k, dict):
                continue
            if k.get("status") not in (None, "active"):
                continue
            ws_id = k.get("workspace_id")
            if ws_id and any(w.get("id") == ws_id for w in candidate_workspaces):
                cred_row = k
                break
    if cred_row is None and isinstance(sessions, list):
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") not in (None, "active"):
                continue
            ws_id = s.get("workspace_id")
            if ws_id and any(w.get("id") == ws_id for w in candidate_workspaces):
                cred_row = s
                break

    # Resolve workspace
    ws = None
    if isinstance(cred_row, dict) and cred_row.get("workspace_id"):
        ws = next((w for w in candidate_workspaces if w.get("id") == cred_row.get("workspace_id")), None)
    if ws is None:
        ws = candidate_workspaces[0]

    member = _find_member_for_workspace(ws.get("id"))
    # If no member row exists, still return identity at workspace level (mapped member unavailable).
    scopes = None
    if isinstance(cred_row, dict):
        sc = cred_row.get("scopes")
        if isinstance(sc, list):
            scopes = sc
        elif isinstance(sc, str):
            scopes = [s for s in sc.split() if s]
        else:
            scopes = cred_row.get("scope") if isinstance(cred_row.get("scope"), list) else None

    resolved["credential"] = cred_row
    resolved["workspace"] = ws
    resolved["member"] = member
    resolved["scopes"] = scopes or ["*"]

    # --- enforce rate/quota if we can attribute to some credential id (or workspace)
    policy = _get_rate_policy()
    logs = _load(request_logs_file)
    credential_id = None
    if isinstance(cred_row, dict):
        credential_id = cred_row.get("id") or cred_row.get("key_id") or cred_row.get("token_id")
    # Fallback to workspace id for counting if no credential id exists.
    counting_cred = credential_id if credential_id is not None else ("ws:" + ws.get("id"))

    minute_since = _iso_minus(60)
    day_since = _iso_day_start()
    used_minute = _count_in_window(logs, minute_since, counting_cred)
    used_day = _count_in_window(logs, day_since, counting_cred)

    # Note: count does not include this in-flight request yet; enforce against limit-1 threshold
    if isinstance(policy.get("per_minute"), int) and used_minute >= policy["per_minute"]:
        _append_log(status="rate_limited", credential_id=counting_cred, workspace_id=ws.get("id"), reason="per_minute", rate_limited=True)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=policy["per_minute"], window="60s", used=used_minute)
    if isinstance(policy.get("per_day"), int) and used_day >= policy["per_day"]:
        _append_log(status="quota_exceeded", credential_id=counting_cred, workspace_id=ws.get("id"), reason="per_day", rate_limited=True)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=policy["per_day"], window="day", used=used_day)

    # Persist usage counters if the store uses them
    usage = _load(usage_file)
    if not isinstance(usage, dict):
        usage = {}
    bucket = usage.get(counting_cred)
    if not isinstance(bucket, dict):
        bucket = {"per_minute": 0, "per_day": 0, "updated_at": now}
    # Recompute from logs for correctness
    bucket["per_minute"] = used_minute + 1
    bucket["per_day"] = used_day + 1
    bucket["updated_at"] = now
    usage[counting_cred] = bucket
    _save(usage_file, usage)

    # log success
    _append_log(status="ok", credential_id=counting_cred, workspace_id=ws.get("id"))

    # --- response
    identity = {
        "workspace": {
            "id": ws.get("id"),
            "clickup_team_id": ws.get("clickup_team_id"),
            "name": ws.get("name"),
            "status": ws.get("status")
        },
        "member": None,
        "scopes": resolved["scopes"]
    }
    if member is not None:
        identity["member"] = {
            "id": member.get("id"),
            "workspace_id": member.get("workspace_id"),
            "clickup_user_id": member.get("clickup_user_id"),
            "username": member.get("username"),
            "email": member.get("email"),
            "full_name": member.get("full_name"),
            "role": member.get("role"),
            "status": member.get("status")
        }

    resp = {
        "whoami": identity
    }

    if includeQuota:
        resp["quota"] = {
            "rate_limit": {
                "per_minute": policy["per_minute"],
                "used": used_minute + 1,
                "remaining": max(0, policy["per_minute"] - (used_minute + 1)),
                "window_seconds": 60
            },
            "daily_quota": {
                "per_day": policy["per_day"],
                "used": used_day + 1,
                "remaining": max(0, policy["per_day"] - (used_day + 1)),
                "window": "day"
            },
            "key": counting_cred
        }

    return resp
